function initBottomPanel(){
  bottomPanel=document.getElementById('bottom-panel');
  panelHandle=document.getElementById('panel-handle');
  panelHandle?.addEventListener('click',()=>bottomPanel?.classList.toggle('collapsed'));
  // Bottom tab switching
  document.querySelectorAll('.bottom-tab').forEach(tab=>{
    tab.addEventListener('click',()=>{
      document.querySelectorAll('.bottom-tab').forEach(t=>t.classList.remove('active'));
      tab.classList.add('active');
      const target=tab.dataset.btab;
      document.querySelectorAll('.btab-content').forEach(c=>c.classList.add('hidden'));
      document.getElementById(`btab-${target}`)?.classList.remove('hidden');
      if (target === 'mobgallery' && typeof renderPaletaDeMonstros === 'function') {
        renderPaletaDeMonstros();
      }
    });
  });
}

// ============================================================
// STATUS
// ============================================================
function updateMapStatus(){
  // A paleta de props NÃO se reconstrói aqui. Esta função só atualiza o rótulo do mapa,
  // mas reconstruía as centenas de miniaturas em canvas da paleta do editor — e é chamada
  // na troca de personagem. Media 50 a 430 ms por chamada: era isso que travava a troca,
  // e o travamento piorava a cada vez. Quem muda os props (carregar cenário, importar,
  // trocar categoria) já chama renderPaletaDeProps por conta própria.
  const name=SCENE_NAMES[currentKey]||currentKey;
  const ciclo = typeof calculoDoCicloDiaNoite === 'function' ? calculoDoCicloDiaNoite(performance.now()) : null;
  const infoTempo = ciclo ? ` (${ciclo.nome})` : '';
  if(statusMap)statusMap.textContent=`🗺️ ${name}${infoTempo}`;

  // Fazendinha: O botão fica sempre disponível (será acessado via HUD geral)
  const btnBuildMode = document.getElementById('btnBuildMode');
  if (btnBuildMode && currentScene !== 'farm') {
    btnBuildMode.classList.remove('hidden');
  }
}
let toastTimer=null;
function showToast(msg){if(!toastEl)return;toastEl.textContent=msg;toastEl.classList.remove('hidden');if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.add('hidden'),2500);}

// ============================================================
// REALISMO E PROFUNDIDADE PARA CENÁRIOS ESTÁTICOS (FOTOS)
// ============================================================

// 1. Sombras de nuvens itinerantes (dá sensação de luz do sol viva sobre a foto)
const nuvensAtmosfericas = Array.from({length: 4}, (_, i) => ({
  x: Math.random() * SCREEN_W * 2,
  y: Math.random() * SCREEN_H,
  scaleX: 240 + Math.random() * 180,
  scaleY: 90 + Math.random() * 70,
  vel: 0.35 + Math.random() * 0.3,
  alpha: 0.12 + Math.random() * 0.08
}));

function renderSombrasDeNuvem(now, mapKey) {
  if (!TEMPO_LIGADO) return;
  if (currentScene !== 'world' || mapKey === 'mega_world' || engineMode === 'world') return;
  if (INTERIORS[mapKey] || (SCENE_NAMES[mapKey] && /caverna|masmorra|porão|interior/i.test(SCENE_NAMES[mapKey]))) return;
  ctx.save();
  nuvensAtmosfericas.forEach(n => {
    n.x -= n.vel;
    if (n.x + n.scaleX < -100) {
      n.x = SCREEN_W + n.scaleX + Math.random() * 300;
      n.y = Math.random() * SCREEN_H;
    }
    const g = ctx.createRadialGradient(n.x, n.y, 10, n.x, n.y, n.scaleX / 2);
    g.addColorStop(0, `rgba(0, 10, 25, ${n.alpha})`);
    g.addColorStop(0.6, `rgba(0, 10, 25, ${n.alpha * 0.5})`);
    g.addColorStop(1, 'rgba(0, 10, 25, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(n.x, n.y, n.scaleX / 2, n.scaleY / 2, -0.15, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.restore();
}

// 2. Vagalumes e Poeira Mágica (partículas vivas flutuando na cena)
const vagalumesMundiais = Array.from({length: 22}, (_, i) => ({
  x: Math.random() * SCREEN_W,
  y: Math.random() * SCREEN_H,
  vx: (Math.random() - 0.5) * 0.6,
  vy: -0.2 - Math.random() * 0.4,
  cor: i % 2 === 0 ? '#fef08a' : '#86efac',
  size: 1.5 + Math.random() * 2,
  offset: Math.random() * 1000
}));

function renderVagalumesEPoeiras(now, mapKey) {
  if (!TEMPO_LIGADO) return;
  if (currentScene !== 'world' || mapKey === 'mega_world' || engineMode === 'world') return;
  const ciclo = calculoDoCicloDiaNoite(now);
  const noiteOuMagico = ciclo.ehNoite || (SCENE_NAMES[mapKey] && /clareira|eco|floresta|bosque|mágic/i.test(SCENE_NAMES[mapKey]));
  if (!noiteOuMagico) return;
  ctx.save();
  vagalumesMundiais.forEach(v => {
    v.x += v.vx + Math.sin(now * 0.002 + v.offset) * 0.4;
    v.y += v.vy;
    if (v.x < 0) v.x = SCREEN_W; if (v.x > SCREEN_W) v.x = 0;
    if (v.y < 0) v.y = SCREEN_H; if (v.y > SCREEN_H) v.y = 0;
    const brilho = (Math.sin(now * 0.004 + v.offset) + 1) / 2;
    if (brilho > 0.15) {
      ctx.globalAlpha = brilho * 0.85;
      ctx.shadowColor = v.cor;
      ctx.shadowBlur = 8;
      ctx.fillStyle = v.cor;
      ctx.beginPath();
      ctx.arc(v.x, v.y, v.size, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  ctx.restore();
}

// 3. Ciclo Dia/Noite com transição suave e gradual de iluminação e atmosfera
const FASES_CICLO = [
  { h: 0.0,  r: 12,  g: 18,  b: 52,  a: 0.60, noite: true,  nome: '🌙 Madrugada Mágica' },
  { h: 5.0,  r: 45,  g: 28,  b: 82,  a: 0.48, noite: true,  nome: '✨ Alvorada mística' },
  { h: 6.5,  r: 251, g: 146, b: 60,  a: 0.28, noite: false, nome: '🌄 Amanhecer Dourado' },
  { h: 8.0,  r: 254, g: 240, b: 138, a: 0.10, noite: false, nome: '☀️ Manhã Serena' },
  { h: 10.0, r: 255, g: 255, b: 255, a: 0.00, noite: false, nome: '☀️ Dia Claro' },
  { h: 15.5, r: 255, g: 255, b: 255, a: 0.00, noite: false, nome: '☀️ Sol da Tarde' },
  { h: 17.5, r: 249, g: 115, b: 22,  a: 0.24, noite: false, nome: '🌅 Entardecer' },
  { h: 18.8, r: 153, g: 27,  b: 27,  a: 0.40, noite: true,  nome: '🌇 Crepúsculo Rubro' },
  { h: 20.0, r: 49,  g: 46,  b: 129, a: 0.52, noite: true,  nome: '🌙 Anoitecer Místico' },
  { h: 22.0, r: 12,  g: 18,  b: 52,  a: 0.60, noite: true,  nome: '🌙 Noite Estrelada' },
  { h: 24.0, r: 12,  g: 18,  b: 52,  a: 0.60, noite: true,  nome: '🌙 Madrugada Mágica' }
];

// Passagem do tempo DESLIGADA. O ciclo rodava um dia inteiro em 120 segundos: a cor
// da tela mudava sem parar, e o que era para ser atmosfera virava um piscar constante
// por cima do mapa. Enquanto não houver um relógio de jogo de verdade — dia longo,
// noite que significa alguma coisa — fica desligado, e o mapa aparece com a cor que
// foi desenhada. `ambience` por cenário entra no mesmo interruptor: escurecer 86% um
// cenário é mudar a cor dele tanto quanto o ciclo mudava.
let TEMPO_LIGADO = false;

// ── Zoom do cenário ─────────────────────────────────────────────────────────────
// A câmera aproxima e segue o jogador, presa às bordas do cenário para nunca mostrar
// o vazio de fora. É isto que deixa o personagem grande na tela sem precisar redesenhar
// sprite nenhum: em vez de aumentar o herói, aproxima-se o mundo inteiro.
// Só vale JOGANDO. No editor a tela continua mostrando o cenário inteiro, porque toda
// a marcação de clique — plantar, arrastar, pintar — é feita em coordenada de cena, e
// uma câmera móvel faria cada clique cair no lugar errado.
let zoomCenario = 1;

// Andar no cenário SEM entrar em jogo. Entrar em jogo arrasta junto HUD, monstros,
// diálogos, cenas de abertura e reposiciona o personagem no spawn — quando tudo o que
// se quer é conferir se o caminho recém-traçado dá passagem. Aqui só o personagem se
// mexe: as ferramentas continuam ativas e o clique continua sendo do editor.
let andarNoEditor = false;

// Monstros VIVOS dentro do editor. Eles ficam congelados ali de propósito — ninguém
// quer posicionar um bicho que sai andando da mão. Mas para montar uma arena e provar
// que ela funciona, era preciso sair do editor, entrar no jogo, e voltar a cada ajuste.
// Este interruptor solta os monstros sem largar as ferramentas.
let combateNoEditor = false;

// Quem manda os monstros se mexerem, atacarem e receberem dano: o jogo de verdade, ou
// o teste de combate dentro do editor.
function monstrosVivos() { return isPlayMode || combateNoEditor || corridaAtiva(); }

function alternarCombateNoEditor(ligar) {
  combateNoEditor = ligar === undefined ? !combateNoEditor : !!ligar;
  // Combate sem poder andar não serve para nada: ligar um liga o outro.
  if (combateNoEditor && !andarNoEditor) alternarAndarNoEditor(true);
  ['combateEditorBtn','combateEditorBtn2'].forEach(id => {
    const b = document.getElementById(id);
    if (!b) return;
    b.classList.toggle('active', combateNoEditor);
    b.textContent = combateNoEditor ? '👾 Monstros soltos' : '👾 Soltar monstros';
  });
  if (combateNoEditor) {
    // Ao soltar, todo mundo volta inteiro e para casa: testar arena com os bichos meio
    // mortos da tentativa anterior não diz nada.
    monsters.forEach(m => {
      if (m.mapKey !== currentKey) return;
      m.dead = false; m.hp = m.maxHp; m.pronto = false; m.abertoAte = 0;
      m.x = m.homeX ?? m.x; m.y = m.homeY ?? m.y; m.respawnAt = 0;
    });
    // Começa o teste com o herói inteiro e livre: entrar numa arena já machucado ou
    // travado de uma rodada anterior não diz nada sobre a arena.
    playerHp = playerMaxHp();
    playerLocked = false; deadUntil = 0; playerHurtUntil = 0;
    // Dizer QUANTOS e ONDE. Com o zoom em 1,6 a câmera mostra um pedaço pequeno do
    // cenário, e soltar 18 bichos espalhados dava a impressão de que o botão não fez nada
    // — todos estavam vivos, só que fora do enquadramento.
    const nomapa = monsters.filter(m => m.mapKey === currentKey);
    const aVista = nomapa.filter(m => {
      const p = telaDoPonto(m.x, m.y);
      return p.x > 0 && p.x < SCREEN_W && p.y > 0 && p.y < SCREEN_H;
    }).length;
    showToast(nomapa.length
      ? `👾 ${nomapa.length} monstros soltos · ${aVista} à vista — as setas apontam o resto`
      : '👾 Nenhum monstro neste cenário ainda.');
  } else {
    monsters.forEach(m => { if (m.mapKey === currentKey) { m.x = m.homeX ?? m.x; m.y = m.homeY ?? m.y; } });
    showToast('👾 Monstros de volta ao posto');
  }
}

// Quem manda o personagem andar e a câmera aproximar: jogando de verdade, ou o modo
// de caminhada do editor.
function personagemAndando() { return isPlayMode || andarNoEditor; }


function alternarAndarNoEditor(ligar) {
  andarNoEditor = ligar === undefined ? !andarNoEditor : !!ligar;
  ['andarEditorBtn','andarEditorBtn2'].forEach(id => {
    const b = document.getElementById(id);
    if (!b) return;
    b.classList.toggle('active', andarNoEditor);
    b.textContent = andarNoEditor ? '🚶 Andando' : '🚶 Andar';
  });
  if (!andarNoEditor) {
    keys.w = keys.a = keys.s = keys.d = false; player.isMoving = false;
    if (!isPlayMode) { document.body.classList.remove('jogando'); playerHud?.classList.add('hidden'); }
    // Parar de andar recolhe os monstros: deixá-los soltos com o personagem parado
    // vira um cerco que atrapalha justamente quem voltou para editar.
    if (combateNoEditor) alternarCombateNoEditor(false);
  }
  else showToast('🚶 WASD anda. As ferramentas continuam funcionando.');
}

function camaraDoCenario() {
  const vw = SCREEN_W / zoomCenario, vh = SCREEN_H / zoomCenario;
  return {
    x: Math.max(vw / 2, Math.min(SCREEN_W - vw / 2, player.x)),
    y: Math.max(vh / 2, Math.min(SCREEN_H - vh / 2, player.y - 20)),
  };
}

function aplicarZoomDoCenario() {
  const c = camaraDoCenario();
  ctx.translate(SCREEN_W / 2, SCREEN_H / 2);
  ctx.scale(zoomCenario, zoomCenario);
  ctx.translate(-c.x, -c.y);
}

// Onde um ponto da cena cai na TELA. As camadas desenhadas por cima do zoom (halo de
// luz, brilho) precisam disto, senão iluminam o canto errado quando a câmera anda.
function telaDoPonto(x, y) {
  if (!(zoomCenario > 1.001)) return { x, y };
  const c = camaraDoCenario();
  return { x: (x - c.x) * zoomCenario + SCREEN_W / 2,
           y: (y - c.y) * zoomCenario + SCREEN_H / 2 };
}

function aplicarZoomCenario(v, salvar = true) {
  zoomCenario = Math.max(1, Math.min(3, Number(v) || 1));
  const rot = document.getElementById('zoomCenarioVal');
  if (rot) rot.textContent = zoomCenario.toFixed(2).replace(/\.?0+$/, '') + '×';
  const ctrl = document.getElementById('zoomCenario');
  if (ctrl && Number(ctrl.value) !== zoomCenario) ctrl.value = zoomCenario;
  if (salvar) {
    try { localStorage.setItem('acordelot_zoom_cenario', String(zoomCenario)); } catch (e) {}
    if (typeof saveAllLayers === 'function' && !IS_PLAY_BUILD) saveAllLayers(false);
  }
}

function calculoDoCicloDiaNoite(now) {
  // Um ciclo completo dura 120 segundos para progredir gradualmente perante os olhos do jogador
  const T = (now % 120000) / 120000;
  const hora = T * 24;
  
  let a = FASES_CICLO[0], b = FASES_CICLO[FASES_CICLO.length - 1];
  for (let i = 0; i < FASES_CICLO.length - 1; i++) {
    if (hora >= FASES_CICLO[i].h && hora <= FASES_CICLO[i+1].h) {
      a = FASES_CICLO[i];
      b = FASES_CICLO[i+1];
      break;
    }
  }
  
  const span = Math.max(0.001, b.h - a.h);
  const prog = (hora - a.h) / span;
  // Suavização cosseno para transição imperceptível
  const f = (1 - Math.cos(prog * Math.PI)) / 2;
  
  const mix = (v1, v2) => Math.round(v1 + (v2 - v1) * f);
  const r = mix(a.r, b.r);
  const g = mix(a.g, b.g);
  const b_val = mix(a.b, b.b);
  const alpha = a.a + (b.a - a.a) * f;
  const ehNoite = alpha >= 0.35 || a.noite;
  const nome = (prog < 0.5) ? a.nome : b.nome;
  
  return { r, g, b: b_val, alpha, ehNoite, nome, hora };
}

let _telaDaNoite = null;
function telaDaNoite() {
  if (!_telaDaNoite) {
    _telaDaNoite = document.createElement('canvas');
    _telaDaNoite.width = SCREEN_W; _telaDaNoite.height = SCREEN_H;
  }
  return _telaDaNoite;
}

function renderCicloDiaNoite(now, mapKey) {
  if (!TEMPO_LIGADO) return;
  if (currentScene !== 'world' || mapKey === 'mega_world' || engineMode === 'world') return;
  const c = calculoDoCicloDiaNoite(now);
  if (c.alpha <= 0.005) return;
  
  ctx.save();
  if (c.ehNoite || c.alpha >= 0.30) {
    // Canvas reaproveitado. Antes era um `createElement('canvas')` de 1024×571 A CADA
    // QUADRO — 60 alocações por segundo de um buffer de 2 MB, com o coletor de lixo
    // correndo atrás. Sozinho, isso já explicava boa parte da travada.
    const escuro = telaDaNoite();
    const eCtx = escuro.getContext('2d');
    eCtx.clearRect(0, 0, SCREEN_W, SCREEN_H);
    eCtx.globalCompositeOperation = 'source-over';
    eCtx.fillStyle = `rgba(${c.r}, ${c.g}, ${c.b}, ${c.alpha})`;
    eCtx.fillRect(0, 0, SCREEN_W, SCREEN_H);
    
    const flicker = Math.sin(now * 0.015) * 6 + Math.cos(now * 0.027) * 4;
    eCtx.globalCompositeOperation = 'destination-out';

    // Luz em volta do Herói (lanterna do viajante suave)
    const raioHeroi = c.ehNoite ? 135 : 105;
    const gJog = eCtx.createRadialGradient(player.x, player.y - 20, 12, player.x, player.y - 20, raioHeroi + flicker);
    gJog.addColorStop(0, 'rgba(0, 0, 0, 1)');
    gJog.addColorStop(0.55, 'rgba(0, 0, 0, 0.6)');
    gJog.addColorStop(1, 'rgba(0, 0, 0, 0)');
    eCtx.fillStyle = gJog;
    eCtx.beginPath(); eCtx.arc(player.x, player.y - 20, raioHeroi + 10, 0, Math.PI * 2); eCtx.fill();

    // Luz em volta de NPCs e pontos luminosos
    npcData.forEach(n => {
      if (n.mapKey !== mapKey || !npcNaCena(n)) return;
      if (['forge_entrance', 'ponto_martelada', 'lago_sorteio', 'porta'].includes(n.type) || (n.name && /fogueira|tocha|luz|lago|forja/i.test(n.name))) {
        const gNpc = eCtx.createRadialGradient(n.x, n.y - 20, 5, n.x, n.y - 20, 100 + flicker * 0.8);
        gNpc.addColorStop(0, 'rgba(0, 0, 0, 0.95)');
        gNpc.addColorStop(1, 'rgba(0, 0, 0, 0)');
        eCtx.fillStyle = gNpc;
        eCtx.beginPath(); eCtx.arc(n.x, n.y - 20, 110, 0, Math.PI * 2); eCtx.fill();
      }
    });
    ctx.drawImage(escuro, 0, 0);
  } else {
    ctx.fillStyle = `rgba(${c.r}, ${c.g}, ${c.b}, ${c.alpha})`;
    ctx.fillRect(0, 0, SCREEN_W, SCREEN_H);
  }
  ctx.restore();
}

// ============================================================
// MAIN LOOP
// ============================================================
// ── Câmera de destaque ───────────────────────────────────────────────────────────
// Aproxima a cena num ponto por alguns segundos, para apresentar alguém sem tirar o
// jogo das mãos do jogador. Entra e sai suavemente; sem destaque ativo não custa nada.
const camDestaque = { ativo: false, x: 0, y: 0, zoom: 1.7, inicio: 0, ms: 3200, rotulo: '' };

function destacar(x, y, opts = {}) {
  camDestaque.ativo = true;
  camDestaque.x = x; camDestaque.y = y;
  camDestaque.zoom = opts.zoom || 1.7;
  camDestaque.ms = opts.ms || 3200;
  camDestaque.rotulo = opts.rotulo || '';
  camDestaque.inicio = performance.now();
}

function forcaDoDestaque(now) {
  if (!camDestaque.ativo) return 0;
  const t = (now - camDestaque.inicio) / camDestaque.ms;
  if (t >= 1) { camDestaque.ativo = false; return 0; }
  const sobe = Math.min(1, t / 0.22);            // aproxima
  const desce = Math.min(1, (1 - t) / 0.25);     // e volta
  const f = Math.min(sobe, desce);
  return f * f * (3 - 2 * f);                    // suaviza as pontas
}

function aplicarCameraDeDestaque(now) {
  const f = forcaDoDestaque(now);
  if (f <= 0.001) return;
  const z = 1 + (camDestaque.zoom - 1) * f;
  // Mantém o alvo no centro da tela enquanto aproxima.
  ctx.translate(SCREEN_W / 2, SCREEN_H / 2);
  ctx.scale(z, z);
  ctx.translate(-camDestaque.x, -camDestaque.y);
}

function renderRotuloDoDestaque(now) {
  const f = forcaDoDestaque(now);
  if (f <= 0.02 || !camDestaque.rotulo) return;
  ctx.save();
  ctx.globalAlpha = f;
  ctx.font = 'bold 22px Outfit, sans-serif';
  ctx.textAlign = 'center';
  const w = ctx.measureText(camDestaque.rotulo).width + 34;
  const y = SCREEN_H - 74;
  ctx.fillStyle = 'rgba(6,9,14,0.88)';
  ctx.fillRect(SCREEN_W/2 - w/2, y - 24, w, 36);
  ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;
  ctx.strokeRect(SCREEN_W/2 - w/2, y - 24, w, 36);
  ctx.fillStyle = '#fde68a';
  ctx.fillText(camDestaque.rotulo, SCREEN_W/2, y);
  ctx.restore();
}

// ── Erro de quadro, visível ──────────────────────────────────────────────────────
// Uma exceção dentro do rAF só aparecia no console, e no celular ninguém tem console.
// O sintoma que chegava era "a tela ficou preta" — inútil para achar a causa. Agora o
// primeiro erro fica escrito na tela, com arquivo e linha, e o jogo continua rodando.
let erroDeQuadro = null;

function registrarErroDeQuadro(e) {
  if (!erroDeQuadro) {
    erroDeQuadro = {
      msg: String(e && e.message || e),
      onde: String((e && e.stack || '').split('\n')[1] || '').trim().slice(0, 120),
      quando: Date.now(),
    };
    console.error('[quadro] exceção no render:', e);
  }
  erroDeQuadro.vezes = (erroDeQuadro.vezes || 0) + 1;
}

function desenharErroDeQuadro() {
  if (!erroDeQuadro) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  const dpr = canvas.width / SCREEN_W;
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.globalAlpha = 1;
  const topo = Math.round(SCREEN_H / 2) - 34;
  ctx.fillStyle = 'rgba(69,10,10,0.95)';
  ctx.fillRect(0, topo, SCREEN_W, 68);
  ctx.fillStyle = '#fecaca';
  ctx.textAlign = 'left';
  ctx.font = 'bold 12px monospace';
  ctx.fillText('ERRO DE RENDER (' + erroDeQuadro.vezes + '×)', 14, topo + 18);
  ctx.font = '11px monospace';
  ctx.fillText(erroDeQuadro.msg.slice(0, 104), 14, topo + 34);
  ctx.fillStyle = '#fca5a5';
  ctx.fillText(erroDeQuadro.onde, 14, topo + 48);
  ctx.fillText('Mande esta mensagem — ela diz o arquivo e a linha.', 14, topo + 62);
  ctx.restore();
}

function loop(now){
  requestAnimationFrame(loop);
  try { quadro(now); } catch (e) { registrarErroDeQuadro(e); }
  try { desenharErroDeQuadro(); } catch (e) {}
}

function quadro(now){
  frameCount++;
  if(now-lastFPSTime>=1000){currentFPS=frameCount;frameCount=0;lastFPSTime=now;if(fpsDisplay)fpsDisplay.textContent=`${currentFPS} FPS`;if(statusFPS)statusFPS.textContent=`${currentFPS} FPS`;talvezCederResolucao();}

  if(engineMode==='worldmap')return;   // desenhado pelo editor de mundo, em canvas próprio

  // A dungeon é vigiada aqui, fora de qualquer ramo de desenho: ela é regra de jogo, e
  // estava dentro do bloco `outdoors`, que não roda em todos os modos — o portão nunca
  // abria no modo andar do editor.
  atualizarDungeon(now);
  // O ciclo de dia e noite pela MESMA razão: ele é regra de jogo — é o que solta os
  // caçadores noturnos — e dentro de um ramo de desenho simplesmente não rodaria em
  // todos os modos. Esta é a armadilha nº 1 do projeto, e ela já custou caro.
  if (personagemAndando()) { atualizarCicloDeTempo(); renderRessonancia(); renderRelogioDoMundo(); }
  // Os números do HUD pela mesma razão: o bloco que os atualizava só roda no modo jogo,
  // e no modo ANDAR a barra ficava congelada nos valores do primeiro quadro.
  if (personagemAndando()) { atualizarNumerosDoHud(); atualizarMissaoNoHud(); }
  if (window.__acompanhanteSalvo) restaurarAcompanhante();
  atualizarAcompanhante(now);
  verificarGatilhosDaHistoria();
  atualizarTrilha(now);
  garantirFolhasDoMapa(currentKey);

  // Avisa a abertura do celular que já há cenário desenhado. Ela fechava por silêncio de
  // rede, e o silêncio caía no vão entre os ícones chegarem e o fundo do mapa ser pedido:
  // a logo saía e o jogador via um retângulo preto.
  if (!window.__cenarioPronto) {
    const bgPronto = bgImages[currentKey];
    if (bgPronto && bgPronto.complete && bgPronto.naturalWidth > 10) window.__cenarioPronto = true;
  }

  const mapKey=isPlayMode?currentKey:(activeMapSelect?.value||currentKey);
  const isMegaWorld = mapKey === 'mega_world';

  const dpr = canvas.width / SCREEN_W;
  // ── Quadro auto-corretivo ───────────────────────────────────────────────────────
  // O zoom do cenário é aplicado com ctx.save() e desfeito ~300 linhas depois, em dois
  // caminhos de saída. Qualquer exceção no meio vazava a transformação — e como o
  // requestAnimationFrame chama isto de novo no quadro seguinte, o vazamento ACUMULAVA:
  // a tela aproximava sozinha até tudo ficar preto, escondendo o erro de verdade.
  // Zerar a matriz aqui faz o pior caso virar um quadro estranho, nunca uma tela preta
  // permanente. O erro em si volta a aparecer no console, que é onde serve.
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.clearRect(0,0,SCREEN_W,SCREEN_H);ctx.imageSmoothingEnabled=false;

  // O criador de mundo é uma área própria: desenha e sai. Isolar assim garante que
  // nenhuma linha do jogo antigo (grade de fotos, placas, cenas) seja afetada.
  if (engineMode === 'mundo') {
    renderMundo(now);
    ctx.restore();
    frameCount++;
    return;
  }
  // Cenário sem arte não é tela preta: é um cenário sem arte. Sem este aviso o sintoma
  // fica idêntico ao de um erro de render, e foi assim que um mapa novo sem fundo salvo
  // passou por bug de zoom.
  if (!isMegaWorld && currentScene !== 'farm'
      && !bgSources[mapKey] && !videoSources[mapKey] && !INTERIORS[mapKey]) {
    ctx.fillStyle = '#150d1f';
    ctx.fillRect(0, 0, SCREEN_W, SCREEN_H);
    ctx.fillStyle = '#e9d5ff';
    ctx.textAlign = 'center';
    ctx.font = 'bold 18px Outfit, sans-serif';
    ctx.fillText('Cenário sem imagem de fundo', SCREEN_W / 2, SCREEN_H / 2 - 12);
    ctx.font = '13px Outfit, sans-serif';
    ctx.fillStyle = '#c4b5fd';
    ctx.fillText(SCENE_NAMES[mapKey] || mapKey, SCREEN_W / 2, SCREEN_H / 2 + 12);
    ctx.fillText('Salve o cenário no editor (💾) para a imagem ser gravada.',
                 SCREEN_W / 2, SCREEN_H / 2 + 34);
    ctx.textAlign = 'left';
    ctx.restore();
    frameCount++;
    return;
  }

  const camOn = isPlayMode && forcaDoDestaque(now) > 0.001;
  const zoomOn = !isMegaWorld && zoomCenario > 1.001;
  // Destaque tem prioridade: ele já é uma câmera com zoom próprio, e as duas somadas
  // aproximariam duas vezes.
  if (camOn || zoomOn) {
    ctx.save();
    if (camOn) aplicarCameraDeDestaque(now); else aplicarZoomDoCenario();
  }

  if (isMegaWorld) {
    if (!bgImages['mega_world']) {
      const img = new Image();
      img.src = 'assets/mega_map_1.jpg';
      bgImages['mega_world'] = img;
    }
    const dims = getMapDimensions('mega_world');
    const viewW = SCREEN_W / megaMapZoom;
    const viewH = SCREEN_H / megaMapZoom;

    megaCameraX = player.x - viewW / 2;
    megaCameraY = player.y - viewH / 2;
    megaCameraX = Math.max(0, Math.min(dims.w - viewW, megaCameraX));
    megaCameraY = Math.max(0, Math.min(dims.h - viewH, megaCameraY));

    ctx.save();
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    ctx.scale(megaMapZoom, megaMapZoom);
    ctx.translate(-megaCameraX, -megaCameraY);

    const bg = bgImages['mega_world'];
    if (bg) {
      try { ctx.drawImage(bg, 0, 0, dims.w, dims.h); } catch(e) {}
    }
  } else {
    if (currentScene === 'farm') {
      if (!bgImages['farm']) {
        const img = new Image();
        img.src = 'assets/cenarios/bg_fazenda.png';
        bgImages['farm'] = img;
      }
      if (bgImages['farm'].complete) {
        ctx.drawImage(bgImages['farm'], 0, 0, SCREEN_W, SCREEN_H);
      }
      // Grade só enquanto há ferramenta armada: construir sem grade é chute, e grade
      // permanente polui o cenário quando o jogador só quer olhar a fazenda.
      // A grade aparece sempre que o toque VAI mexer na ilha: com prop na mão, com um
      // projeto de habitat armado, e também no modo recolher — antes ela sumia justo aí,
      // que é quando mais se precisa de referência para acertar a peça.
      if (propParaColocar || projetoArmado || modoRecolher) renderGradeDaFazenda();
      // O ciclo de dia/noite será desenhado por cima depois
    } else if(currentScene==='world'||!isPlayMode){
      const vid = videoDoMapa(mapKey);
      if (vid) ctx.drawImage(vid, 0, 0, SCREEN_W, SCREEN_H);
      else {
        garantirFundo(mapKey);
        const bg = bgImages[mapKey];
        if (bg?.complete) comSuavizacao(() => ctx.drawImage(bg, 0, 0, SCREEN_W, SCREEN_H));
      }
      if (currentScene === 'world' && mapKey !== 'mega_world') renderSombrasDeNuvem(now, mapKey);
    }
    else { const st=interiorDef()?.still?.(); if(st)ctx.drawImage(st,0,0,SCREEN_W,SCREEN_H); }
  }

  // Caminhada do editor: só move o personagem e nada mais. Sem HUD, sem monstro, sem
  // diálogo — e sem tirar o clique das ferramentas.
  if(!isPlayMode && andarNoEditor && currentScene === 'world'){
    let dx=0,dy=0;
    if(keys.w)dy-=1;if(keys.s)dy+=1;if(keys.a)dx-=1;if(keys.d)dx+=1;
    if(stick.active){dx=stick.x;dy=stick.y;}
    const len=Math.hypot(dx,dy);
    player.isMoving=len>0.15;
    if(player.isMoving){
      const sprint=keys.shift||len>0.92;
      const spd=(sprint?player.sprintSpeed:player.speed)*Math.min(1,len);
      dx/=len; dy/=len;
      player.direction = direcaoDoMovimento(dx, dy, player.direction);
      const tx=player.x+dx*spd, ty=player.y+dy*spd;
      // Respeita a colisão pintada: é justamente isso que se quer testar ao andar.
      if(canMoveTo(tx,ty)){player.x=tx;player.y=ty;}
      else if(canMoveTo(tx,player.y))player.x=tx;
      else if(canMoveTo(player.x,ty))player.y=ty;
      player.animTimer+=spd;
      if(player.animTimer>passoDaAnimacao(sprint)){player.animTimer=0;player.animFrame=(player.animFrame+1)%(personagemAtivo().cols||4);}
    } else { player.animFrame = quadroParado(); player.animTimer = 0; }

    // Mochila e atributos existem enquanto se ANDA, não só no antigo modo jogo. Como
    // "jogar" hoje é justamente andar pelo mundo, deixar o HUD fora daqui tirava o
    // inventário do jogo inteiro.
    document.body.classList.add('jogando');
    playerHud?.classList.toggle('hidden', shopOpen||inventoryOpen||charOpen||fichaAberta());
    atualizarBotaoDeAtaque(now);

    // Os monstros só eram atualizados DENTRO do bloco de modo jogo. Soltá-los no editor
    // os deixava vivos para o dano mas parados no lugar — metade do teste.
    // updateRespawn entra junto: sem ele, um herói que tenha caído por qualquer outro
    // caminho ficaria travado para sempre, porque a recuperação vive só no modo jogo.
    if (combateNoEditor) { updateRespawn(now); updateMonsters(now); updateDrops(now); }
  }

  if(isPlayMode){
    // Cão de guarda: se o jogador está travado mas NADA está no comando (cena, diálogo,
    // menu, forja, captura, caminhada roteirizada), destrava. Um `controle: false` que
    // não foi desfeito congelava o personagem sem nenhuma pista na tela.
    // Diálogo sem roteiro é fantasma: não desenha nada mas engole todas as teclas,
    // porque o keydown devolve cedo quando dlg.state !== CLOSED.
    if (dlg.state !== DLG_STATE.CLOSED && !dlg.script) endDialogue();

    if (playerLocked && !CUT.ativo && dlg.state === DLG_STATE.CLOSED &&
        !shopOpen && !inventoryOpen && !charOpen && !forging && !capturaAtiva &&
        !(CUT.caminhadas && CUT.caminhadas.length)) {
      if (!window.__travadoDesde) window.__travadoDesde = now;
      else if (now - window.__travadoDesde > 900) {
        playerLocked = false; window.__travadoDesde = 0;
        console.warn('[Acordelot] destravado pelo cão de guarda — nada estava no comando');
      }
    } else window.__travadoDesde = 0;

    if(!playerLocked){
      let dx=0,dy=0;
      if(keys.w)dy-=1;if(keys.s)dy+=1;if(keys.a)dx-=1;if(keys.d)dx+=1;
      if(stick.active){dx=stick.x;dy=stick.y;}
      const len=Math.hypot(dx,dy);
      player.isMoving=len>0.15;
      if(player.isMoving){ guardaAte = 0;
        // Full deflection on the stick sprints, same as holding Shift on a keyboard.
        const sprint=keys.shift||len>0.92;
        const spd=(sprint?player.sprintSpeed:player.speed)*Math.min(1,len);
        dx/=len;dy/=len;
        player.direction = direcaoDoMovimento(dx, dy, player.direction);
        const tx=player.x+dx*spd,ty=player.y+dy*spd;
        if(canMoveTo(tx,ty)){player.x=tx;player.y=ty;}
        else if(canMoveTo(tx,player.y))player.x=tx;
        else if(canMoveTo(player.x,ty))player.y=ty;
        const dims = isMegaWorld ? getMapDimensions('mega_world') : { w: SCREEN_W, h: SCREEN_H };
        player.x = Math.max(28, Math.min(dims.w - 28, player.x));
        player.y = Math.max(32, Math.min(dims.h - 32, player.y));
        const quadros = personagemAtivo().cols || 4;
        player.animTimer += spd;
        if (player.animTimer >= passoDaAnimacao(sprint)) {
          player.animTimer = 0;
          player.animFrame = (player.animFrame + 1) % quadros;
          // o pé encosta duas vezes por ciclo: é aí que sai poeira e som
          if (player.animFrame === 0 || player.animFrame === Math.floor(quadros / 2)) {
            spawnDust(player.x, player.y); playStep(sprint);
          }
        }
      } else {player.animFrame=quadroParado();player.animTimer=0;}
      checkTransitions();checkDoors();checkNPCProx();
    }
    updateRespawn(now);updateMonsters(now);updateDrops(now);
    // The dialogue box owns the bottom of the screen, and movement is locked anyway.
    const talking=dlg.state!==DLG_STATE.CLOSED;
    wasdPanel?.classList.toggle('hidden', talking);
    const act=actionAvailable();
    keyE?.classList.toggle('disabled', !act);
    if(keyE&&act)keyE.textContent = 'E · ' + ({attack:'Atacar',shop:'Loja',forge:'Forjar',enter:'Entrar',enterForge:'Entrar',talk:'Falar',travel:'Viajar',gather:'Coletar'}[act]);
    // The stick zone covers a big chunk of the lower-left screen, which is exactly where
    // the dialogue box sits. Pull the whole overlay while talking so every tap reaches
    // the canvas — the player is locked in place anyway.
    // Some com o overlay em QUALQUER momento em que o jogador não comanda o personagem:
    // diálogo, cutscene, menu aberto, forja, captura. Checar só o diálogo deixava o
    // joystick e o botão de ação por cima das falas das cenas, no celular.
    // Não use CUT.ativo aqui: há cenas que devolvem o controle no meio (o "chegue perto
    // do guarda"), e esconder o joystick nessas horas trava o jogo no celular. Quem
    // responde a pergunta certa — "o jogador manda no personagem agora?" — é playerLocked.
    // `capturaAtiva` fica FORA desta lista de propósito: a janela de afinação dura pouco
    // mais de dois segundos e o botão de ação é o único jeito de ressoar no celular.
    // Escondê-lo aí garantiria o "dispersou" em toda captura.
    const semControle = talking || playerLocked ||
                        shopOpen || inventoryOpen || charOpen || forging;
    if(touchControls&&document.body.classList.contains('mobile-play')){
      touchControls.classList.toggle('hidden', semControle);
      if(semControle&&stick.active){stick.active=false;stick.x=stick.y=0;}
    }
    // Toda ação precisa de rótulo: sem entrada aqui o botão do celular ficava com o
    // texto da ação anterior, e o jogador não sabia que era para ressoar.
    const ACT_LABEL={attack:'Atacar',shop:'Loja',forge:'Forjar',enter:'Entrar',enterForge:'Entrar',
      talk:'Falar',travel:'Viajar',gather:'Coletar',ressoar:'RESSOAR',martelar:'Martelar',
      sair:'Sair',sortear:'Sortear',entrarPorta:'Entrar',forjarEscala:'Forjar Escala'};
    if(touchAction&&act)touchAction.textContent=ACT_LABEL[act];
    touchAction?.classList.toggle('disabled', !act);
    playerHud?.classList.toggle('hidden', talking||shopOpen||inventoryOpen||charOpen||fichaAberta());
    atualizarBotaoDeAtaque(now);
    atualizarNumerosDoHud();
    // Interiors are their own space: the outdoor map's NPCs, chatter and overlays must
    // not bleed through onto the shop floor.
    const outdoors=currentScene==='world' || currentScene==='farm';
    if(outdoors){
      npcData.forEach(npc=>{if(npc.mapKey!==currentKey||!npcNaCena(npc))return;
        if(currentScene==='farm')return;   // a fazenda nao tem placa, porta nem NPC de mundo
        (NPC_DRAW[npc.type]||DEFAULT_NPC_DRAW)(ctx,npc,now);});
      renderDrops(now);   // on the ground, under everyone
      renderMonsters(now); renderInvocacoes(now); renderSubidaDeNivel(now); renderRotaDaProximaCamara(now); renderLugaresDeCena(now);
      renderObjetos(now, 'atras');   // pé acima do jogador: ele passa na frente
    }
    const L=getLayers(currentKey);
    updateDust();renderDust();
    // Brief ring on entering play so the character is never lost on a busy map.
    if(now < spawnFlashUntil){
      const t=(spawnFlashUntil-now)/1600, pulse=(Math.sin(now*0.012)+1)/2;
      ctx.save();
      ctx.globalAlpha=Math.min(1,t)*0.9;
      ctx.strokeStyle='#facc15'; ctx.lineWidth=3;
      ctx.beginPath(); ctx.ellipse(player.x,player.y,30+pulse*8,13+pulse*4,0,0,Math.PI*2); ctx.stroke();
      ctx.globalAlpha=Math.min(1,t)*0.5;
      ctx.beginPath(); ctx.ellipse(player.x,player.y,46+pulse*10,20+pulse*5,0,0,Math.PI*2); ctx.stroke();
      ctx.restore();
    }
    {const pW=outdoors?player.width:HEROI_BASE.interiorW*heroiEscala,
           pH=outdoors?player.height:HEROI_BASE.interiorH*heroiEscala;
     renderFerramenta(now,pW,pH,true);}      // atrás do corpo (andando para cima)
    // Fora do bloco de cenário externo: numa sala fechada a cena não avançava nunca,
    // congelava no primeiro `esperar` e deixava o jogador travado para sempre.
    atualizarCena(now);
    if (frameCount % 30 === 0) silenciarVideosDeInterior();

    // A aura vem ANTES do herói: brilho é luz em volta do corpo, não um véu por cima.
    renderAuraDaLamina(now);
    renderPlayer();
    if(!player.oculto){const pW=outdoors?player.width:HEROI_BASE.interiorW*heroiEscala,
                       pH=outdoors?player.height:HEROI_BASE.interiorH*heroiEscala;
     renderFerramenta(now,pW,pH,false);      // na frente, nas outras direções
     renderHat(pW,pH);renderAura(now,pH);}
    if(outdoors){
      renderObjetos(now, 'frente');  // pé abaixo do jogador: cobre o personagem
      // O ECO DA FAZENDA VEM POR CIMA DO HABITAT.
      //
      // A ordem do quadro é: objetos de trás → monstros → objetos da frente. Como o corte
      // entre "trás" e "frente" é feito pela linha do JOGADOR e não pela de cada bicho, a
      // ilha do habitat caía na leva da frente sempre que o jogador estava acima dela — e
      // era desenhada DEPOIS do Eco, escondendo justamente o bicho que mora nela.
      //
      // O Eco de fazenda vive EM CIMA da ilha; não existe ângulo em que a ilha deva
      // cobri-lo. Então ele sai numa passada própria, depois de tudo.
      if (currentScene === 'farm') renderEcosPorCima(now);
      if (currentScene === 'farm') tagarelarEcosDaFazenda();
      acompanharArena();
      if (currentScene === 'farm' && propParaColocar && typeof mouseCanvasX !== 'undefined') {
        renderGhostProp(propParaColocar, mouseCanvasX, mouseCanvasY);
      }
      renderAttackSwing(now);
      renderGatherSwing(now);
      ctx.drawImage(L.fgCanvas,0,0);renderHeroiPorTras(currentKey);renderDoorMarkers(now);updateLeaves();renderLeaves();
      renderVagalumesEPoeiras(now, currentKey);
      renderCicloDiaNoite(now, currentKey);
      updatePath();renderPath(now);
      updateAmbient(now);renderSpeech(now);renderFloaters(now);
      // Prompt over whatever the action button is currently pointing at — not just
      // NPCs. A door you can't see is a door that doesn't exist.
      const ACT_PROMPT={sortear:'E  ·  Tentar a Sorte',ressoar:'E  ·  RESSOAR',talk:'E  ·  Falar',travel:'E  ·  Viajar',gather:'E  ·  Coletar',forjar:'E  ·  Montar escala',enterForge:'E  ·  Entrar',martelar:'E  ·  Martelar',entrarPorta:'E  ·  Entrar',invocar:'E  ·  Invocar Eco',alimentar:'E  ·  Ver o Eco',cena:'E  ·  Ver',obra:'E  ·  Martelar'};
      const act=actionAvailable();
      const tgt = act==='talk' ? talkTarget()
                : act==='travel' ? signpostTarget()
                : act==='sortear' ? lagoTarget()
                : act==='entrarPorta' ? portaTarget()
                : act==='martelar' ? marteladaTarget()
                : act==='gather' ? (spotTarget() || propColetavelTarget())
                : act==='cena' ? lugarDeCenaTarget()
                : act==='obra' ? habitatTarget()
                : act==='invocar' ? habitatTarget()
                : act==='alimentar' ? ecoDaFazendaTarget()
                : act==='fazenda' ? plantaTarget()
                : act==='enterForge' ? forgeDoorTarget() : null;
      // O rótulo da planta muda com o estado dela: um botão só, três respostas.
      if (act==='cena' && tgt) ACT_PROMPT.cena = 'E  ·  ' + tgt.verbo;
      if (act==='fazenda' && tgt) {
        const a = acaoDaPlanta(tgt);
        ACT_PROMPT.fazenda = a==='colher' ? 'E  ·  Colher'
                           : a==='regar'  ? 'E  ·  Regar' : 'E  ·  Crescendo';
      }
      if(tgt&&!speech.some(s=>s.npc===tgt)){
        // Prop não é NPC: a caixa dele vem de objetoBounds, senão o balão sai no meio do
        // tronco em vez de acima da copa.
        const b = tgt.prop ? objetoBounds(tgt) : npcBounds(tgt);
        // Realce só no alcance. Anel permanente numa floresta inteira de árvores viraria
        // poluição visual — o que o jogador precisa saber é "esta aqui dá para bater".
        if (tgt.prop) {
          const pulso = (Math.sin(now*0.006)+1)/2;
          ctx.save();
          ctx.strokeStyle = `rgba(251,191,36,${0.35+pulso*0.35})`;
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.ellipse(tgt.x, tgt.y, 26, 10, 0, 0, Math.PI*2);
          ctx.stroke();
          ctx.restore();
        }
        drawBubble(ctx,tgt.x,b.y-3,ACT_PROMPT[act],{bg:'rgba(251,191,36,0.92)',border:'#78350f',fg:'#1c1917',font:'bold 11px Outfit, sans-serif'});
      }

      // Interactable world elements get a soft beacon so they're findable from a distance.
      npcData.forEach(n=>{
        if(n.mapKey!==currentKey)return;
        if(n.type==='ponto_martelada'&&!marteladaTarget())return;
        // O gatilho do sorteio é invisível de propósito: o lago dourado já está pintado
        // no vídeo do cenário, então desenhar um anel por cima só sujaria a arte.
        if(n.type==='lago_sorteio')return;
        if(n.type==='porta'&&!n.interior)return;      // porta sem destino é só marcador
        if(n.type==='porta'){
          // Entrada de cenário especial: pilar de luz e faíscas subindo. Uma porta
          // discreta no meio do mato passa despercebida.
          const p2=(Math.sin(now*0.003)+1)/2;
          ctx.save();
          const g=ctx.createLinearGradient(n.x,n.y-150,n.x,n.y+10);
          g.addColorStop(0,'rgba(253,230,138,0)');
          g.addColorStop(1,`rgba(253,230,138,${0.16+p2*0.16})`);
          ctx.fillStyle=g;
          ctx.fillRect(n.x-34,n.y-150,68,160);
          ctx.globalAlpha=0.5+p2*0.4;
          ctx.strokeStyle='#fde68a'; ctx.lineWidth=2.5;
          ctx.shadowColor='#fbbf24'; ctx.shadowBlur=22;
          ctx.beginPath(); ctx.ellipse(n.x,n.y,40+p2*6,15+p2*3,0,0,Math.PI*2); ctx.stroke();
          ctx.fillStyle='#fde68a';
          for(let i=0;i<5;i++){
            const f=((now*0.0004)+i*0.2)%1;
            ctx.globalAlpha=(1-f)*0.8;
            ctx.fillRect(n.x-26+((i*37)%52), n.y-f*130, 2.5, 2.5);
          }
          ctx.restore();
          const b2=npcBounds(n);
          drawBubble(ctx,n.x,b2.y-6,SCENE_NAMES[n.interior]||INTERIORS[n.interior]?.name||'Entrada',
            {bg:'rgba(20,14,6,.9)',border:'#fde68a',fg:'#fde68a',font:'bold 11px Outfit, sans-serif'});
          return;
        }
        if(!['forge_entrance','signpost','spot_wood','spot_stone','ponto_martelada','porta','lago_sorteio'].includes(n.type))return;
        const d=Math.hypot(player.x-n.x,player.y-n.y);
        if(d>340)return;
        const b=npcBounds(n);
        const pulse=(Math.sin(now*0.0035)+1)/2;
        const near=d<=(n.triggerRadius||70);
        ctx.save();
        ctx.globalAlpha=(near?0.55:0.28)+pulse*0.2;
        ctx.strokeStyle=near?'#fde047':'#fbbf24'; ctx.lineWidth=2;
        ctx.beginPath();
        ctx.ellipse(n.x,n.y,b.w*0.55+pulse*3,b.w*0.24+pulse*2,0,0,Math.PI*2);
        ctx.stroke();
        ctx.restore();
      });
    }
    if (outdoors) {
      renderMarcadoresDeNPC(now); renderCaptura(now);
      renderCombo(now); renderAnuncio(now);
      atualizarLaminaVoando(now); renderLaminaVoando(now); renderMira(now);
      atualizarOrbita(now); renderOrbita(now);
      atualizarChuvaDeLancas(now); renderChuva(now);
      renderGrito(now); atualizarSono(now);
      renderEstadosDeMonstro(now);
      renderFaroisDeBau(now);
      renderAltarDaForja(now);
      renderTrocaDeHeroi(now); renderClarao(now);
    }
    else { renderSpeech(now); renderFloaters(now); }
    if (!IS_PLAY_BUILD) renderMotivoDoTravamento();
    else renderMarcadoresDoInterior(now);
    if (camOn || zoomOn) ctx.restore();
    renderBussolaDeMonstros(now);
    renderBussolaDeRecursos(now);
    renderFantasmaDaFazenda(now);
    renderPlacaDaRota(now);
    if (camOn) renderRotuloDoDestaque(now);
    renderAmbiente();
    renderDlg(now);
    renderNotasGuia(now);
    renderCena(now);
    if(statusPos)statusPos.textContent=`X: ${Math.round(player.x)}  Y: ${Math.round(player.y)}`;
  } else {
    // No modo Cena quem desenha os NPCs é renderSceneOverlay, que além do sprite mostra
    // seleção, alça e raio de gatilho. Desenhar aqui TAMBÉM pintava cada NPC duas vezes
    // por quadro: com zoom as duas passadas saíam em posições diferentes e apareciam
    // dois personagens; sem zoom sobrepunham e escureciam as bordas transparentes.
    if (engineMode !== 'scene') {
      npcData.forEach(npc=>{if(npc.mapKey!==mapKey||!npcNaCena(npc))return;(NPC_DRAW[npc.type]||DEFAULT_NPC_DRAW)(ctx,npc,now);});
    }
    renderObjetos(now, 'todos');   // sem isto o editor não mostrava o que você plantou
    // O personagem aparece no editor enquanto a caminhada estiver ligada — sem ele não
    // há como ver se o caminho pintado dá passagem. Ele vem ANTES do teto: desenhado
    // depois, passava por cima de tudo e o teto pintado não parecia fazer efeito
    // nenhum — foi por isso que o trabalho de pintura sumia ao testar.
    if (andarNoEditor && !player.oculto) { renderAuraDaLamina(now); renderPlayer(); }
    const L=getLayers(mapKey);ctx.drawImage(L.fgCanvas,0,0);
    if (andarNoEditor) renderHeroiPorTras(mapKey);
    // TUDO do editor desenha DENTRO da câmera. renderSceneOverlay desenha os NPCs de
    // novo (é ele quem mostra seleção, alça e raio de gatilho); com o `restore` antes
    // dele, essa segunda passada saía sem zoom enquanto a primeira saía com — dois
    // NPCs na tela, um por cima do outro, deslocados. O `restore` vai para o fim.
    if (engineMode === 'scene') {
      renderVagalumesEPoeiras(now, mapKey);
      renderCicloDiaNoite(now, mapKey);
      renderAmbiente();
      renderSceneOverlay(now);
    } else if (engineMode === 'collision') renderCollisionOverlay(mapKey);
    if (camOn || zoomOn) ctx.restore();
    if(statusPos)statusPos.textContent=`X: ${Math.round(mouseCanvasX)}  Y: ${Math.round(mouseCanvasY)}`;
  }

  if (isMegaWorld) {
    ctx.restore();
  }
  ctx.restore();
}

// ============================================================
// INIT
// ============================================================
// ── Fundo de mapa: a ÚNICA coisa que se suaviza ───────────────────────────────────
//
// O jogo desliga a suavização em todo quadro, e está certo: sprite é pixel art, e
// suavizar come a borda dura que a arte pede. Só que o FUNDO DO MAPA não é pixel art —
// é ilustração pintada, e ele nunca é desenhado no tamanho em que foi salvo:
//
//   · os mapas antigos têm 1024×571 e sobem para a densidade da tela;
//   · os que você gerou por último têm 2752×1536 e DESCEM para 1024×571.
//
// Descer 2752 para 1024 sem suavizar é o pior dos dois: sem média entre os pixels
// vizinhos, dois em cada três somem inteiros e o que fica serrilha e cintila a cada
// passo da câmera. Era por isso que o cenário novo, de resolução muito maior, aparecia
// PIOR que o velho.
//
// Sprite continua sem suavização. A troca vale um desenho e volta ao normal em seguida.
function comSuavizacao(desenhar) {
  const antes = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  try { desenhar(); } finally { ctx.imageSmoothingEnabled = antes; }
}

// ── Teto de resolução que cede sozinho ────────────────────────────────────────────
//
// Um número fixo aqui erra nos dois sentidos: baixo demais borra o celular bom, alto
// demais engasga o celular fraco, e não há como saber qual dos dois está na mão de quem
// abriu o jogo. Então começa nítido e só desce quando o próprio aparelho mostrar que não
// dá conta — três segundos seguidos abaixo de 45 quadros. É medida, não suposição.
//
// Desce, e não volta a subir: um aparelho que já engasgou vai engasgar de novo, e ficar
// alternando entre dois tamanhos de canvas pisca a tela a cada troca.
const TETO = { valor: 3, ruinsSeguidos: 0 };
// Exposto para diagnóstico: quando alguém disser "está borrado", a primeira pergunta é
// se o aparelho cedeu resolução ou se o teto nunca subiu. `TETO.valor` responde as duas.
window.TETO = TETO;

function talvezCederResolucao() {
  if (TETO.valor <= 2 || !currentFPS) return;
  TETO.ruinsSeguidos = currentFPS < 45 ? TETO.ruinsSeguidos + 1 : 0;
  if (TETO.ruinsSeguidos >= 3) { TETO.valor = 2; setupHighDPICanvas(); }
}

function setupHighDPICanvas() {
  if (!canvas) return;
  // A resolução interna acompanha o tamanho REAL em tela, não um múltiplo fixo. Num
  // monitor grande o canvas era desenhado a 2048px e esticado para ~2600, o que
  // borrava a arte; agora ele desenha na densidade que o painel realmente tem.
  const r = canvas.getBoundingClientRect();
  const densidade = window.devicePixelRatio || 1;
  const larguraCss = r.width > 40 ? r.width : SCREEN_W;
  // Quantos pixels reais existem para cada unidade lógica do jogo. O piso era 2, o que
  // obrigava um monitor comum (densidade 1) a desenhar 2048×1142 para exibir 1024×571:
  // quatro vezes mais pixel do que a tela mostra, todo quadro. Como o canvas já é
  // `image-rendering: pixelated`, um pixel de desenho por pixel de tela é o que dá a
  // borda dura que a arte pede — supersampling aqui só amaciava o que não devia amaciar.
  // O TETO É MEDIDO, NÃO CHUTADO.
  //
  // Este número é literalmente "quantos pixels a tela tem para cada unidade do jogo".
  // Prendê-lo em 2 num celular de densidade 3 manda o navegador esticar um quadro de
  // 2048 px para os ~2600 do painel — e, como o canvas é `image-rendering: pixelated`,
  // essa esticada é sem suavização: sai serrilhado, não borrado. Foi essa a queda de
  // nitidez. Mas o teto 2 nasceu de um motivo real: em densidade 3 o custo por quadro
  // derrubava a taxa. Então em vez de escolher entre nitidez e fluidez de uma vez para
  // todo aparelho, o teto começa alto e CEDE se o aparelho reclamar — ver `TETO`.
  const escala = Math.min(TETO.valor, Math.max(1, (larguraCss * densidade) / SCREEN_W));
  const targetW = Math.round(SCREEN_W * escala);
  const targetH = Math.round(SCREEN_H * escala);
  if (canvas.width !== targetW || canvas.height !== targetH) {
    canvas.width = targetW;
    canvas.height = targetH;
    ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false;   // pixel art: nunca suavizar
  }
}

document.addEventListener('DOMContentLoaded',()=>{
  canvas=document.getElementById('gameCanvas');
  ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
  setupHighDPICanvas();
  // ── O TECLADO DO CELULAR NÃO É UMA MUDANÇA DE TELA ─────────────────────────────
  //
  // Abrir o teclado para digitar e-mail e senha encolhe a janela: no celular isso dispara
  // um `resize` a cada quadro da animação de subida do teclado, e antes cada um deles
  // refazia o canvas — trocar `canvas.width` apaga o buffer e força um redesenho inteiro.
  // Vinte vezes em meio segundo, e a tela TREME. Era isso que acontecia ao entrar na
  // conta, e por isso só acontecia ali: é a única tela do jogo com campo de texto.
  //
  // Duas defesas: só a LARGURA conta (o teclado muda a altura, não a largura), e ainda
  // assim com uma pausa para o redimensionamento assentar antes de medir.
  let _prazoDeMedir = null, _larguraMedida = 0;
  function remedirCanvas(imediato = false) {
    clearTimeout(_prazoDeMedir);
    const agir = () => {
      const larg = Math.round(canvas.getBoundingClientRect().width);
      if (!imediato && larg === _larguraMedida) return;   // só o teclado: ignora
      _larguraMedida = larg;
      setupHighDPICanvas();
    };
    if (imediato) { agir(); return; }
    _prazoDeMedir = setTimeout(agir, 180);
  }
  remedirCanvas(true);
  window.addEventListener('resize', () => remedirCanvas());
  window.addEventListener('orientationchange', () => setTimeout(() => remedirCanvas(true), 200));
  // Seguro contra a janela mudar de tamanho sem avisar. O Safari do celular encolheu a
  // área do jogo ao abrir uma caixa nativa e não disparou `resize` nenhum: o jogo voltou
  // desenhado em menos de metade da tela, com o resto preto, e ficou assim. Refazer a
  // conta quando a aba volta a aparecer custa uma medição e desfaz esse tipo de sequela.
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) setTimeout(() => remedirCanvas(true), 60);
  });
  window.addEventListener('focus', () => setTimeout(() => remedirCanvas(true), 60));
  window.addEventListener('pageshow', () => setTimeout(() => remedirCanvas(true), 60));
  // O observador do canvas passa pelo MESMO filtro. Ligado direto no `setupHighDPICanvas`
  // ele era a maior fonte do tremor: o teclado subindo encolhe o canvas quadro a quadro, e
  // cada aviso do observador refazia o buffer inteiro.
  if (window.ResizeObserver) new ResizeObserver(() => remedirCanvas()).observe(canvas);
  bindCanvasEvents();
  skinShopVideo=document.getElementById('skinShopVideo');
  loadingOverlay=document.getElementById('loadingOverlay');
  toastEl=document.getElementById('toastEl');
  questNotif=document.getElementById('questNotification');
  questNotifTitle=document.getElementById('questNotifTitle');
  questNotifObj=document.getElementById('questNotifObj');
  nameInputOverlay=document.getElementById('nameInputOverlay');
  playerNameInput=document.getElementById('playerNameInput');
  confirmNameBtn=document.getElementById('confirmNameBtn');
  fpsDisplay=document.getElementById('fpsDisplay');
  statusMap=document.getElementById('statusMap');
  statusPos=document.getElementById('statusPos');
  statusFPS=document.getElementById('statusFPS');
  activeMapSelect=document.getElementById('activeMapSelect');
  npcHierarchyList=document.getElementById('npcHierarchyList');
  inspEmpty=document.getElementById('inspEmpty');
  inspNPCPanel=document.getElementById('inspNPCPanel');
  inspName=document.getElementById('insp_name'); inspType=document.getElementById('insp_type');
  inspX=document.getElementById('insp_x'); inspY=document.getElementById('insp_y');
  inspMap=document.getElementById('insp_map'); inspDialogue=document.getElementById('insp_dialogue');
  inspRadius=document.getElementById('insp_radius'); inspScale=document.getElementById('insp_scale');
  inspFlip=document.getElementById('insp_flip'); inspTriggered=document.getElementById('insp_triggered');
  applyNPCBtn=document.getElementById('applyNPCBtn'); deleteNPCBtn=document.getElementById('deleteNPCBtn');
  playBtn=document.getElementById('playBtn'); stopBtn=document.getElementById('stopBtn');
  saveProjectBtn=document.getElementById('saveProjectBtn');
  brushSizeSelect=document.getElementById('brushSizeSelect');
  fillDefaultBtn=document.getElementById('fillDefaultBtn'); clearLayerBtn=document.getElementById('clearLayerBtn'); saveLayersBtn=document.getElementById('saveLayersBtn');
  resetGridBtn=document.getElementById('resetGridBtn'); saveWorldBtn=document.getElementById('saveWorldBtn');
  wasdPanel=document.getElementById('wasdPanel');
  keyW=document.getElementById('keyW'); keyA=document.getElementById('keyA'); keyS=document.getElementById('keyS'); keyD=document.getElementById('keyD');
  keyE=document.getElementById('keyE');
  keyE?.addEventListener('click',()=>{initAudio();doAction();});
  document.getElementById('partySlot0')?.addEventListener('click', () => { initAudio(); trocarHeroiDoTime(0); });
  document.getElementById('partySlot1')?.addEventListener('click', () => { initAudio(); trocarHeroiDoTime(1); });
  activeQuestsList=document.getElementById('activeQuestsList');

  initBottomPanel();

  // Mode tabs
  document.querySelectorAll('.mode-tab').forEach(btn=>btn.addEventListener('click',()=>setMode(btn.dataset.mode)));
  if(!CRIADOR_DE_MUNDO_ATIVO){
    document.querySelector('.mode-tab[data-mode="mundo"]')?.style.setProperty('display','none');
    document.getElementById('assetDock')?.style.setProperty('display','none');
    document.body.classList.remove('modo-mundo');
    setMode('scene');   // abre sempre no editor de cena, aconteça o que acontecer antes
  }
  // Scene subtools
  document.querySelectorAll('[data-stool]').forEach(btn=>btn.addEventListener('click',()=>setSceneTool(btn.dataset.stool)));
  // Collision subtools
  document.querySelectorAll('[data-ctool]').forEach(btn=>btn.addEventListener('click',()=>setCollisionTool(btn.dataset.ctool)));
  // ── Roda de combate ───────────────────────────────────────────────────────────
  const btnAtk = document.getElementById('botaoAtaque');
  if (btnAtk) {
    // `pointerdown` e não `click`: no celular o clique só dispara ao SOLTAR o dedo, e um
    // botão de ataque que espera o dedo sair parece atrasado.
    //
    // Um botão, duas funções: com monstro ao alcance ele ataca; com placa, porta, NPC ou
    // ponto de coleta ele age. Antes havia dois botões disputando o mesmo canto da tela
    // e um disparava o outro.
    btnAtk.addEventListener('pointerdown', e => {
      e.preventDefault(); initAudio();
      // Habilidade engatilhada: PRESSIONAR abre a mira, e soltar arremessa. É o gesto de
      // segurar para apontar — o golpe comum não sai neste toque.
      if (abrirMiraSetima()) return;
      const act = actionAvailable();
      if (act && act !== 'attack' && act !== 'ressoar') doAction();
      else doAttack();
    });
    // Soltar no botão dispara o arremesso. Sem isto, largar o dedo em cima do botão não
    // contava como soltar e a mira ficava presa na tela.
    btnAtk.addEventListener('pointerup', e => { if (mirandoSetima()) { e.preventDefault(); soltarSetima(); } });
    btnAtk.addEventListener('pointercancel', () => { if (mirandoSetima()) soltarSetima(); });
    // Arrastar com o dedo em cima do botão também aponta.
    btnAtk.addEventListener('pointermove', e => {
      if (!mirandoSetima()) return;
      e.preventDefault();
      const r = canvas.getBoundingClientRect();
      apontarSetima((e.clientX - r.left) * SCREEN_W / r.width, (e.clientY - r.top) * SCREEN_H / r.height);
    });
    btnAtk.addEventListener('contextmenu', e => e.preventDefault());
  }

  // Ressoar em botão próprio, e só ele ressoa.
  const btnRes = document.getElementById('botaoRessoar');
  if (btnRes) {
    btnRes.addEventListener('pointerdown', e => { e.preventDefault(); initAudio(); ressoar(); });
    btnRes.addEventListener('contextmenu', e => e.preventDefault());
  }
  // As três habilidades ainda não fazem nada: ficam desabilitadas no HTML em vez de
  // abrirem um aviso de "em breve" a cada toque.
  // Os três botões pequenos voltaram a ser vagas. Os quatro golpes viraram uma corrente
  // no botão grande, e ocupá-los com os mesmos golpes seria oferecer duas portas para a
  // mesma coisa. Ficam reservados para habilidades de verdade.
  // Os três botões chamam a habilidade do PERSONAGEM EM CAMPO, e não uma habilidade fixa.
  // Amarrá-las direto na Lâmina e na Sétima dava as habilidades do Achilles para a Wins:
  // ela apertava e saía a espada dele, que não é a arma dela.
  ['habilidade1','habilidade2','habilidade3'].forEach((id, i) => {
    const b = document.getElementById(id);
    if (!b) return;
    b.addEventListener('pointerdown', e => {
      e.preventDefault(); initAudio();
      // Na fazenda estes botões são Construir, Recolher e Regar, e quem responde é o
      // `onclick` posto por `aplicarHudDaFazenda`. Este ouvinte NÃO é substituído por
      // aquele — os dois disparam — então tocar em "Construir" também lançava a Espada
      // de Dó Maior no meio da horta.
      if (currentScene === 'farm') return;
      const hab = habilidadesDoHeroi()[i];
      if (habilidadeUsavel(hab)) hab.usar();
      else if (hab) showToast(`${hab.nome} ainda está trancada — abra na ficha.`);
    });
    b.addEventListener('contextmenu', e => e.preventDefault());
  });
  sincronizarBotoesDeHabilidade();

  ['andarEditorBtn','andarEditorBtn2'].forEach(id =>
    document.getElementById(id)?.addEventListener('click',()=>alternarAndarNoEditor()));
  ['combateEditorBtn','combateEditorBtn2'].forEach(id =>
    document.getElementById(id)?.addEventListener('click',()=>alternarCombateNoEditor()));
  document.getElementById('areaFecharBtn')?.addEventListener('click',()=>areaFechar());
  document.getElementById('areaDesfazerBtn')?.addEventListener('click',()=>areaDesfazerPonto());
  // Teclado do contorno. Só responde com a ferramenta em uso e fora de campo de texto,
  // senão Backspace apagaria ponto enquanto se escreve o nome de um NPC.
  document.addEventListener('keydown',e=>{
    if(engineMode!=='collision'||collisionTool!=='area')return;
    const a=e.target;
    if(a&&(a.tagName==='INPUT'||a.tagName==='TEXTAREA'||a.isContentEditable))return;
    if(e.key==='Enter'){e.preventDefault();areaFechar();}
    else if(e.key==='Backspace'){e.preventDefault();areaDesfazerPonto();}
    else if(e.key==='Escape'){e.preventDefault();areaCancelar();}
  });
  // WV subtools
  document.querySelectorAll('[data-wvtool]').forEach(btn=>btn.addEventListener('click',()=>setWVTool(btn.dataset.wvtool)));

  // ▶ Jogar: na primeira vez abre o menu; depois RETOMA de onde parou, no mesmo mapa
  // e na mesma posição. Editar e testar é um vaivém constante — refazer o caminho a
  // cada teste é o que mais custa tempo.
  playBtn?.addEventListener('click', () => {
    initAudio();
    const menu = document.getElementById('mainMenuOverlay');
    if (jogoIniciado) { togglePlay(); return; }
    if (menu && !isPlayMode) {
      menu.classList.remove('hidden');
      renderHeroAvatars();
    } else togglePlay();
  });
  // Segurar Shift ao clicar força o menu, para quando você quiser recomeçar de fato.
  playBtn?.addEventListener('mousedown', e => { if (e.shiftKey) jogoIniciado = false; });
  stopBtn?.addEventListener('click',()=>togglePlay());
  // Monstros entram aqui também: o botão diz "Salvar", e quem clica nele espera que
  // TUDO seja gravado. Faltar os monstros aqui já custou uma sessão de edição.
  saveProjectBtn?.addEventListener('click',()=>{saveAllLayers(false,'todos');saveNPCs();saveMonsters();saveObjetos();showToast('💾 Projeto salvo!');});
  saveLayersBtn?.addEventListener('click',()=>saveAllLayers(true,'todos'));
  saveWorldBtn?.addEventListener('click',()=>saveAllLayers(true,'todos'));
  brushSizeSelect?.addEventListener('change',e=>brushSize=parseInt(e.target.value));
  document.getElementById('autoRoofBtn')?.addEventListener('click',()=>{
    autoRoofFromRoad(activeMapSelect?.value||currentKey);
  });
  fillDefaultBtn?.addEventListener('click',()=>{
    const k=activeMapSelect?.value||currentKey;const L=getLayers(k);
    L.roadCtx.clearRect(0,0,SCREEN_W,SCREEN_H);L.fgCtx.clearRect(0,0,SCREEN_W,SCREEN_H);L.doorCtx.clearRect(0,0,SCREEN_W,SCREEN_H);
    L.roadCtx.fillStyle='#22c55e';L.roadCtx.fillRect(430,0,164,SCREEN_H);L.roadCtx.fillRect(0,230,SCREEN_W,140);
    ['road','fg','door'].forEach(t=>marcarCamadaSuja(k,t));
    invalidateRoadPaint(k);invalidateDoorMarkers(k);
    showToast('🪄 Caminho padrão criado!');saveAllLayers(false);
  });
  clearLayerBtn?.addEventListener('click',()=>{
    const k=activeMapSelect?.value||currentKey;const L=getLayers(k);
    L.roadCtx.clearRect(0,0,SCREEN_W,SCREEN_H);L.fgCtx.clearRect(0,0,SCREEN_W,SCREEN_H);L.doorCtx.clearRect(0,0,SCREEN_W,SCREEN_H);
    ['road','fg','door'].forEach(t=>marcarCamadaSuja(k,t));
    invalidateRoadPaint(k);invalidateDoorMarkers(k);
    showToast('🗑️ Camadas limpas!');saveAllLayers(false);
  });
  resetGridBtn?.addEventListener('click',()=>{
    gridPos={'1_0':{col:1,row:0},'2_0':{col:2,row:0},'0_1':{col:0,row:1},'1_1':{col:1,row:1}};
    rebuildGrid();showToast('🔄 Grid reorganizado!');saveAllLayers(false);
  });
  document.getElementById('resetGridBtn2')?.addEventListener('click',()=>resetGridBtn?.click());
  document.getElementById('saveWorldBtn2')?.addEventListener('click',()=>saveWorldBtn?.click());

  const startPlacing=()=>{if(engineMode!=='scene')setMode('scene');npcPlacingMode=true;canvas.classList.add('cursor-crosshair');showToast('📍 Clique no mapa para posicionar o NPC');};
  document.getElementById('addNPCHierBtn')?.addEventListener('click',startPlacing);
  document.getElementById('addNPCToolBtn')?.addEventListener('click',startPlacing);

  applyNPCBtn?.addEventListener('click',()=>{
    if(!selectedNPC)return;
    selectedNPC.name=inspName?.value||selectedNPC.name;
    selectedNPC.type=inspType?.value||selectedNPC.type;
    selectedNPC.x=parseInt(inspX?.value)||selectedNPC.x;
    selectedNPC.y=parseInt(inspY?.value)||selectedNPC.y;
    selectedNPC.mapKey=inspMap?.value||selectedNPC.mapKey;
    selectedNPC.dialogue=inspDialogue?.value||'none';
    selectedNPC.triggerRadius=parseInt(inspRadius?.value)||80;
    selectedNPC.scale=parseFloat(inspScale?.value)||1;
    selectedNPC.flipX=inspFlip?.checked||false;
    selectedNPC.triggered=inspTriggered?.checked||false;
    refreshNPCHierarchy();saveNPCs();showToast('✅ NPC salvo!');
  });
  deleteNPCBtn?.addEventListener('click',()=>{
    if(!selectedNPC)return;const i=npcData.indexOf(selectedNPC);if(i>=0)npcData.splice(i,1);
    deselectNPC();refreshNPCHierarchy();saveNPCs();showToast('🗑️ NPC removido!');
  });

  confirmNameBtn?.addEventListener('click',()=>{
    const v=playerNameInput?.value?.trim();if(!v||v.length<1){showToast('⚠️ Digite um nome!');return;}
    playerName=v;hideNameInput();dlg.stepId=dlg._nextStep;dlg.state=DLG_STATE.CLOSED;setTimeout(()=>processStep(),100);
  });
  playerNameInput?.addEventListener('keydown',e=>{if(e.key==='Enter')confirmNameBtn?.click();});

  // Guard against an empty/unknown value: assigning it to currentKey blanks the whole
  // editor (no background, no layers) and everything looks broken.
  activeMapSelect?.addEventListener('change',()=>{
    const v=activeMapSelect.value;
    if(!bgSources[v]){activeMapSelect.value=currentKey;return;}
    currentKey=v;updateMapStatus();refreshNPCHierarchy();
  });

  // WASD mobile
  if(keyW){[[keyW,'w'],[keyA,'a'],[keyS,'s'],[keyD,'d']].forEach(([el,k])=>{
    ['mousedown','touchstart'].forEach(ev=>el.addEventListener(ev,e=>{e.preventDefault();initAudio();keys[k]=true;el.classList.add('active');}));
    ['mouseup','mouseleave','touchend'].forEach(ev=>el.addEventListener(ev,e=>{e.preventDefault();keys[k]=false;el.classList.remove('active');}));
  });}

  rebuildGrid();refreshMapSelect();updateMapStatus();
  weBind();
  bindTouchControls();
  initMobileEditorToggle();
  initModoTablet();
  initFazendaUI();
  initCustomProps();
  bindStoreUI();
  bindCharUI();
  initDialogueEditor();
  initGalleryDragAndDrop();
  initRealtimeInspectorControls();
  initOrnateInventory();
  initForgeUI();
  loadToolSheets();
  loadMagiaSheets();
  loadSpotSheets();
  initHotbar();
  initScenarioUploader();
  initMegaWorldControls();
  initTesteDeCena();
  blockIOSGestures();
  // O LAÇO COMEÇA ANTES de tudo que é opcional. Ele era iniciado na ÚLTIMA linha da
  // inicialização, depois de entrar em modo jogo, abrir menu e ligar o autosave — e uma
  // exceção em qualquer um desses passos deixava o jogo sem nunca desenhar um quadro:
  // tela preta, sem controle, sem mensagem. Desenhar é a única coisa que não pode
  // depender do resto dar certo.
  requestAnimationFrame(loop);

  // Cada passo isolado: um que falhe não leva os outros junto.
  try { if(wantsMobilePlay())enterMobilePlay(); } catch(e){ console.error('[Acordelot] entrada em jogo:', e); }
  try { abrirMenuInicialSePreciso(); } catch(e){ console.error('[Acordelot] menu inicial:', e); }
  try { iniciarAutosave(); } catch(e){ console.error('[Acordelot] autosave:', e); }
  setTimeout(()=>loadingOverlay?.classList.add('hidden'),600);
});

// Botão de teste: libera a trava de "já rodou" e dispara a abertura na hora, para
// conseguir rever a cena quantas vezes precisar durante a autoria.
function initTesteDeCena() {
  document.getElementById('testarCenaBtn')?.addEventListener('click', async () => {
    if (!CUT.roteiros.length) await carregarCatalogoDeCenas();
    // Roda a cena do mapa aberto no editor; sem cena aqui, cai na abertura.
    const mapa = activeMapSelect?.value || currentKey;
    const r = cenaDoMapaCrua(mapa) || window.__abertura;
    if (!r) { showToast('⚠️ Nenhuma cena cadastrada em assets/cutscenes/index.json'); return; }
    if (!bgSources[r.mapa]) { showToast('⚠️ O cenário da cena não existe mais: ' + r.mapa); return; }
    CUT.jaRodou = {};
    try { localStorage.removeItem(CHAVE_DAS_CENAS); } catch (e) {}
    if (CUT.ativo) encerrarCena();
    iniciarCena(r);
    showToast(`🎬 ${r.nome || r.id}`);
  });
}

function initMegaWorldControls() {
  const zoomRange = document.getElementById('zoomRange');
  const zoomVal = document.getElementById('zoomVal');
  const playerSizeRange = document.getElementById('playerSizeRange');
  const playerSizeVal = document.getElementById('playerSizeVal');
  const playerSpeedRange = document.getElementById('playerSpeedRange');
  const playerSpeedVal = document.getElementById('playerSpeedVal');
  const megaBar = document.getElementById('megaControlBar');
  const megaMinBtn = document.getElementById('megaMinBtn');
  const megaCloseBtn = document.getElementById('megaCloseBtn');
  const megaPillBtn = document.getElementById('megaPillBtn');
  const megaModeBtn = document.getElementById('megaModeBtn');
  const uploadMega2KBtn = document.getElementById('uploadMega2KBtn');
  const megaFileInput = document.getElementById('megaFileInput');


  if (uploadMega2KBtn && megaFileInput) {
    uploadMega2KBtn.addEventListener('click', () => megaFileInput.click());
    megaFileInput.addEventListener('change', async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;
      showToast('⏳ Processando imagem HD...');
      const reader = new FileReader();
      reader.onload = async (ev) => {
        const b64 = ev.target.result;
        const img = new Image();
        img.onload = () => {
          bgImages['mega_world'] = img;
          showToast(`🎉 Imagem HD Carregada! (${img.naturalWidth}x${img.naturalHeight}px)`);
        };
        img.src = b64;
        try {
          await fetch('/upload_image', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ filename: 'mega_map_1.jpg', image: b64 })
          });
        } catch(err) {}
      };
      reader.readAsDataURL(file);
    });
  }

  // Mouse Wheel Zoom / Sprite Scaling directly on canvas!
  if (canvas) {
    canvas.addEventListener('wheel', (e) => {
      const targetObj = (engineMode === 'mundo' ? mundoPropSel : objetoSelecionado);
      if (targetObj && !isPlayMode) {
        e.preventDefault();
        const factor = e.deltaY < 0 ? 1.08 : 0.92;
        if (engineMode === 'mundo') {
          targetObj.ex = Math.max(0.1, Math.min(10, (targetObj.ex || targetObj.escala || 1) * factor));
          targetObj.ey = Math.max(0.1, Math.min(10, (targetObj.ey || targetObj.escala || 1) * factor));
          saveMundo();
        } else {
          targetObj.escala = Math.max(0.1, Math.min(10, (targetObj.escala || 1) * factor));
          aplicarEscalaDoObjeto(targetObj.escala);
          saveObjetos();
        }
        return;
      }
      if (engineMode === 'mundo') { e.preventDefault(); mundoZoom(e.deltaY); return; }
      if (currentKey !== 'mega_world' && activeMapSelect?.value !== 'mega_world') return;
      e.preventDefault();
      const delta = e.deltaY < 0 ? 0.15 : -0.15;
      megaMapZoom = Math.max(1.0, Math.min(4.0, megaMapZoom + delta));
      if (zoomRange) zoomRange.value = megaMapZoom.toFixed(1);
      if (zoomVal) zoomVal.textContent = megaMapZoom.toFixed(1) + 'x';
    }, { passive: false });
  }

  if (zoomRange) {
    zoomRange.addEventListener('input', (e) => {
      megaMapZoom = parseFloat(e.target.value);
      if (zoomVal) zoomVal.textContent = megaMapZoom.toFixed(1) + 'x';
    });
  }

  if (playerSizeRange) {
    playerSizeRange.addEventListener('input', (e) => {
      playerCustomHeight = parseInt(e.target.value, 10);
      if (playerSizeVal) playerSizeVal.textContent = playerCustomHeight + 'px';
      player.height = playerCustomHeight;
      player.width = Math.round(playerCustomHeight * (48 / 64));
    });
  }

  if (playerSpeedRange) {
    playerSpeedRange.addEventListener('input', (e) => {
      const spd = parseFloat(e.target.value);
      if (playerSpeedVal) playerSpeedVal.textContent = spd.toFixed(1);
      player.speed = spd;
      player.sprintSpeed = spd * 1.7;
    });
  }

  if (megaMinBtn) {
    megaMinBtn.addEventListener('click', () => {
      megaBar?.classList.add('hidden');
      megaPillBtn?.classList.remove('hidden');
    });
  }

  if (megaPillBtn) {
    megaPillBtn.addEventListener('click', () => {
      megaPillBtn?.classList.add('hidden');
      megaBar?.classList.remove('hidden');
    });
  }

  if (megaCloseBtn) {
    megaCloseBtn.addEventListener('click', () => {
      megaBar?.classList.add('hidden');
      megaPillBtn?.classList.add('hidden');
    });
  }

  if (megaModeBtn) {
    megaModeBtn.addEventListener('click', () => {
      currentKey = 'mega_world';
      if (activeMapSelect) activeMapSelect.value = 'mega_world';
      megaBar?.classList.remove('hidden');
      megaPillBtn?.classList.remove('hidden');
      const dims = getMapDimensions('mega_world');
      player.x = dims.w / 2;
      player.y = dims.h / 2;
      if (!isPlayMode) togglePlay();
      showToast('🗺️ Mega Cenário 2K (Modo Zoom & Câmera) Ativado!');
    });
  }

  const photoRecriadoBtn = document.getElementById('photoRecriadoBtn');
  if (photoRecriadoBtn) {
    photoRecriadoBtn.addEventListener('click', () => {
      currentKey = 'photo_recriado';
      if (activeMapSelect) activeMapSelect.value = 'photo_recriado';
      megaBar?.classList.add('hidden');
      megaPillBtn?.classList.add('hidden');
      player.x = 688;
      player.y = 384;
      if (!isPlayMode) togglePlay();
      showToast('📸 Cenário Recriado de Foto Ativado!');
    });
  }

  initMainMenu();
  initQuestBuilder();
  loadHeroSprites();
}

// Todas as folhas são 4x4 com fundo branco, no mesmo formato do Arthur: linha 0 de
// frente, 1 de costas, 2 de lado (espelhada para a esquerda), 4 quadros por linha.
// As antigas hero_male_2.png / hero_female_*.png eram capturas de tela, não sprites —
// era por isso que os personagens novos não apareciam.
// ============================================================
// ELENCO
// Cada personagem é uma CLAVE — a clave define o registro em que ele canta, e daí saem
// o papel em combate e a afinidade com os Ecos. É a mesma ideia do elemento nos jogos
// de time, só que tirada da própria teoria musical em vez de emprestada do fogo/água.
//
// `base` soma aos atributos do jogador: o personagem traz o corpo, o jogador traz a
// perícia. Assim trocar de personagem muda como se joga sem apagar o que se conquistou.
// ============================================================
const HERO_DEFINITIONS = {
  'achilles': {
    // O id continua 'achilles': é a chave dos arquivos de folha, da ficha de medidas e dos
    // saves já gravados. O nome exibido é que virou Akles.
    id: 'achilles', name: 'Akles', class: 'Espadachim da Clave', gender: 'Masculino',
    // Folha normalizada: 8 quadros por fileira, quatro direções próprias (não há
    // espelhamento — o desenho de perfil direito é diferente do esquerdo).
    // `src` é a folha padrão (a de caminhada). `folhas` lista as outras por estado —
    // cada uma com a própria contagem de colunas, porque idle tem menos quadros que
    // caminhada. Todas foram casadas na mesma escala e na mesma célula por
    // ferramentas/casar_folhas_heroi.py: sem isso o herói mudava de tamanho ao parar.
    src: 'assets/personagens/herois/achilles_caminhada.png', cols: 8, rows: 4,
    // Uma folha por estado. `medidas` (achilles_folhas.json) traz o tamanho do CORPO e
    // a linha dos PÉS de cada uma — sem isso o desenho teria que usar a célula, que é
    // mais alta que o personagem para caber a espada erguida do golpe vertical, e o
    // herói sairia com metade do tamanho nessa folha.
    medidas: 'assets/personagens/herois/achilles_folhas.json',
    folhas: {
      andar:    { src: 'assets/personagens/herois/achilles_caminhada.png' },
      parado:   { src: 'assets/personagens/herois/achilles_parado.png' },
      guarda:   { src: 'assets/personagens/herois/achilles_guarda.png' },
      ataque:   { src: 'assets/personagens/herois/achilles_ataque.png' },
      vertical: { src: 'assets/personagens/herois/achilles_ataque_vertical.png' },
      estocada: { src: 'assets/personagens/herois/achilles_estocada.png' },
      giro:     { src: 'assets/personagens/herois/achilles_giro.png' },
    },
    linhas: { down: 0, up: 1, left: 2, right: 3 },
    // Quadro em que cada direção fica ao PARAR. A folha é de caminhada e não tem pose
    // parada de verdade, então usa-se o quadro de passagem — o único em que as pernas
    // estão juntas. Voltar ao quadro 0 deixava o herói congelado com o pé no ar.
    // Medido pela largura ocupada pelos pés em cada quadro.
    parado: { down: 5, up: 5, left: 2, right: 3 },
    face: 'assets/personagens/herois/achilles_face.png', avatar: 'assets/personagens/herois/achilles_face.png',
    weapon: 'Teclado Espada', clave: 'Sol', registro: 'Agudo',
    papel: 'Investida', raridade: 5, desbloqueado: true,
    base: { vida: 0, dano: 0, ritmo: 0, afinacao: 0 },
    lema: 'Quem entra primeiro é quem dá o tom.',
  },

  'wins': {
    id: 'wins', name: 'Wins', class: 'Cantora das Escalas', gender: 'Feminino',
    src: 'assets/personagens/herois/wins_caminhada.png', cols: 7, rows: 4,
    // Mesma ficha de medidas do Achilles: as doze folhas dos dois personagens foram
    // casadas juntas, então ambos têm corpo de 124 px e os pés na mesma linha. É isso que
    // impede o herói de mudar de tamanho ao trocar de personagem.
    medidas: 'assets/personagens/herois/achilles_folhas.json',
    folhas: {
      andar:     { src: 'assets/personagens/herois/wins_caminhada.png' },
      // Ela ainda não tem folha de parado nem de guarda. Sem elas o desenho cai na de
      // caminhada e o quadro de descanso abaixo segura a pose — a mesma muleta que o
      // Achilles usou até a folha de idle dele chegar.
      estocada:  { src: 'assets/personagens/herois/wins_estocada.png' },
      varredura: { src: 'assets/personagens/herois/wins_varredura.png' },
      vertical:  { src: 'assets/personagens/herois/wins_vertical.png' },
      giro:      { src: 'assets/personagens/herois/wins_giro.png' },
    },
    linhas: { down: 0, up: 1, left: 2, right: 3 },
    // Medido pela largura que os pés ocupam em cada quadro da folha de caminhada.
    parado: { down: 1, up: 5, left: 3, right: 5 },
    // Corrente própria. A lança alcança mais que a espada e pesa menos, então ela abre
    // rasteira para desequilibrar, sobe na nota alta, avança na estocada e remata girando
    // com as ondas em volta. Os números são diferentes dos do Achilles de propósito: é a
    // diferença de moveset que faz trocar de personagem significar alguma coisa.
    combo: [
      { folha: 'varredura', ms: 360, alcance: 1.30, dano: 0.9, rotulo: 'Varredura' },
      { folha: 'vertical',  ms: 480, alcance: 1.15, dano: 1.3, rotulo: 'Nota Alta' },
      { folha: 'estocada',  ms: 400, alcance: 1.80, dano: 1.6, rotulo: 'Estocada Cantada',
        empurrao: 34 },
      { folha: 'giro',      ms: 620, alcance: 1.45, dano: 2.2, rotulo: 'Uníssono',
        emVolta: true, remate: true },
    ],
    face: 'assets/personagens/herois/wins_face.png',
    avatar: 'assets/personagens/herois/wins_face.png',
    weapon: 'Lança-Microfone', clave: 'Fá', registro: 'Médio',
    // Entra no elenco só depois de a história apresentá-la (bandeira `wins_no_grupo`).
    // Vinha ligada de fábrica e aparecia no trocador desde a primeira cena.
    papel: 'Alcance', raridade: 5, desbloqueado: false,
    base: { vida: 0, dano: 0, ritmo: 0, afinacao: 0 },
    lema: 'A nota certa alcança mais longe que o braço.',
  },

  // ── HUANS, Clã das Cordas ────────────────────────────────────────────────────
  // A arma dele é um machado-guitarra, e o moveset sai disso: peso de machado com o
  // alcance de um braço de guitarra. Comparado aos outros dois, ele bate MAIS FORTE e
  // MAIS DEVAGAR — é a terceira resposta à mesma pergunta, e é o que faz escolher entre
  // os três significar alguma coisa. O Akles investe, a Wins alcança, o Huans quebra.
  'huans': {
    id: 'huans', name: 'Huans', class: 'Clã das Cordas', gender: 'Masculino',
    src: 'assets/personagens/herois/huans_caminhada.png', cols: 8, rows: 4,
    // Mesma ficha dos outros dois: as dezenove folhas dos três foram casadas juntas, e
    // é por isso que os três têm 162 px de corpo e os pés na mesma linha. Sem isso o
    // herói mudaria de tamanho ao trocar de personagem.
    medidas: 'assets/personagens/herois/achilles_folhas.json',
    folhas: {
      andar:     { src: 'assets/personagens/herois/huans_caminhada.png' },
      parado:    { src: 'assets/personagens/herois/huans_parado.png' },
      guarda:    { src: 'assets/personagens/herois/huans_guarda.png' },
      corte:     { src: 'assets/personagens/herois/huans_corte.png' },
      vertical:  { src: 'assets/personagens/herois/huans_vertical.png' },
      estocada:  { src: 'assets/personagens/herois/huans_estocada.png' },
      giro:      { src: 'assets/personagens/herois/huans_giro.png' },
    },
    linhas: { down: 0, up: 1, left: 2, right: 3 },
    // Quadro de descanso por direção, na folha de caminhada — só vale enquanto a folha
    // de parado não estiver carregada.
    parado: { down: 0, up: 0, left: 2, right: 2 },
    // Corrente própria. Machado é peso: cada golpe demora mais que o equivalente dos
    // outros dois e dói mais. O remate `giro` é o mais lento do jogo e o único que
    // atinge em volta — quem erra o tempo dele fica exposto, e é essa a troca.
    combo: [
      { folha: 'corte',    ms: 420, alcance: 1.20, dano: 1.1, rotulo: 'Corte de Corda' },
      { folha: 'vertical', ms: 560, alcance: 1.05, dano: 1.7, rotulo: 'Queda de Braço' },
      { folha: 'estocada', ms: 460, alcance: 1.65, dano: 1.5, rotulo: 'Traste Longo',
        empurrao: 40 },
      { folha: 'giro',     ms: 720, alcance: 1.50, dano: 2.6, rotulo: 'Acorde Maior',
        emVolta: true, remate: true },
    ],
    face: 'assets/personagens/herois/huans_face.png',
    avatar: 'assets/personagens/herois/huans_face.png',
    weapon: 'Machado-Guitarra', clave: 'Dó', registro: 'Grave',
    papel: 'Impacto', raridade: 5, desbloqueado: true,
    base: { vida: 0, dano: 0, ritmo: 0, afinacao: 0 },
    lema: 'Corda que não vibra é só arame.',
  },
};
let selectedHeroId = 'achilles';

function personagemAtivo() { return HERO_DEFINITIONS[selectedHeroId] || HERO_DEFINITIONS.achilles; }

// Em que quadro o herói descansa, por direção. Sem isto ele parava no quadro 0, que na
// folha de caminhada é o CONTATO — perna esticada e pé no ar. Parecia travado no meio
// do passo. Quando existir folha de parado (idle) de verdade, esta função sai de cena.
// Distância percorrida entre um quadro e o próximo. Contar por distância e não por
// tempo é o que impede o pé de deslizar: se o personagem anda mais devagar, a passada
// desacelera junto. Antes eram 19 por quadro, 152 px por ciclo completo — quase três
// alturas do personagem, e por isso ele parecia patinar.
const PASSO_DA_CAMINHADA = 13, PASSO_DA_CORRIDA = 9;
function passoDaAnimacao(sprint) { return sprint ? PASSO_DA_CORRIDA : PASSO_DA_CAMINHADA; }

// Direção que o personagem encara, com HISTERESE. Escolher só por `|dx| > |dy|` faz a
// direção trocar de eixo a cada quadro quando o dedo está perto da diagonal — o sprite
// piscava entre lado e frente, e dava a sensação de andar para onde não se pediu. Aqui o
// eixo atual só é abandonado quando o outro ganha por uma margem.
const MARGEM_DE_TROCA = 1.35;

function direcaoDoMovimento(dx, dy, atual) {
  const ax = Math.abs(dx), ay = Math.abs(dy);
  const noEixoX = atual === 'left' || atual === 'right';
  // Já andando na horizontal: só vira para a vertical se ela for claramente maior.
  if (noEixoX && ay <= ax * MARGEM_DE_TROCA) return dx < 0 ? 'left' : 'right';
  if (!noEixoX && ax <= ay * MARGEM_DE_TROCA) return dy < 0 ? 'up' : 'down';
  return ax > ay ? (dx < 0 ? 'left' : 'right') : (dy < 0 ? 'up' : 'down');
}

function quadroParado() {
  const p = personagemAtivo().parado;
  if (!p) return 0;
  return p[player.direction] ?? p.down ?? 0;
}
function personagensDesbloqueados() {
  return Object.values(HERO_DEFINITIONS).filter(h => h.desbloqueado);
}

// ============================================================
// ESTRUTURA DE EQUIPE DE 2 PERSONAGENS (ESTILO GENSHIN IMPACT)
// ============================================================
const partyState = {
  // O segundo lugar nasce VAZIO de propósito: o time de dois é a promessa, e a vaga
  // aberta no HUD é o que faz o jogador querer o primeiro sorteio.
  // Time de dois: Achilles em campo, Wins na reserva. A tecla 2 (ou o segundo retrato)
  // troca quem está jogando — e como o combo é por personagem, trocar muda o moveset
  // inteiro, não só o sprite.
  party: ['achilles', 'wins'],
  activePartyIndex: 0,
  heroStates: { 'achilles': { hp: 100 }, 'wins': { hp: 100 } }
};

function heroiNoSlot(slotIdx) {
  return partyState.party[slotIdx] || null;
}

function trocarHeroiDoTime(slotIndex, silent = false) {
  if (slotIndex < 0 || slotIndex >= 2) return false;
  const novoHeroId = partyState.party[slotIndex];
  if (!novoHeroId || !HERO_DEFINITIONS[novoHeroId]) return false;

  // Se já for o herói ativo no momento, ignora
  if (slotIndex === partyState.activePartyIndex && selectedHeroId === novoHeroId) {
    return true;
  }

  // 1. Salva a vida atual do herói que está saindo do campo de batalha
  if (selectedHeroId) {
    if (!partyState.heroStates[selectedHeroId]) partyState.heroStates[selectedHeroId] = {};
    partyState.heroStates[selectedHeroId].hp = playerHp;
  }

  // 2. Atualiza o slot ativo e o herói selecionado
  partyState.activePartyIndex = slotIndex;
  selectedHeroId = novoHeroId;

  // 3. Restaura o estado de vida do novo herói
  const mHp = typeof playerMaxHp === 'function' ? playerMaxHp() : 100;
  const hs = partyState.heroStates[novoHeroId] || { hp: mHp };
  partyState.heroStates[novoHeroId] = hs;
  playerHp = Math.max(1, Math.min(mHp, hs.hp !== undefined ? hs.hp : mHp));

  // 4. Atualiza a sprite ativa
  if (typeof processedHeroSprites !== 'undefined' && processedHeroSprites[novoHeroId]) {
    processedSprite = processedHeroSprites[novoHeroId];
  }

  // 4b. A corrente do combo ZERA na troca. Cada personagem tem a própria sequência, e
  // carregar o passo 3 do Achilles para dentro do moveset da Wins faria o golpe seguinte
  // sair da folha errada — ou de folha que ela nem tem.
  comboPasso = 0; comboAte = 0; comboTravaAte = 0;
  golpeEmCurso = null; attackAnimUntil = 0; guardaAte = 0;
  mira = null;                 // mira armada não atravessa a troca

  // 4c. Os três botões passam a mostrar as habilidades de quem entrou.
  sincronizarBotoesDeHabilidade();
  setimaEngatilhada = false;

  // 5. Troca com PESO. Só poeira não dizia que algo aconteceu — a personagem simplesmente
  // virava outra no mesmo quadro. Agora há um anel de entrada que se abre do chão, o nome
  // de quem entrou anunciado na tela, e a poeira como acabamento.
  trocaEfeito = { inicio: performance.now(), nome: (HERO_DEFINITIONS[novoHeroId] || {}).name || novoHeroId };
  anunciar(((HERO_DEFINITIONS[novoHeroId] || {}).name || novoHeroId).toUpperCase(), 1300);
  if (typeof spawnDust === 'function') {
    for (let i = 0; i < 14; i++) spawnDust(player.x + (Math.random() - 0.5) * 30, player.y + (Math.random() - 0.5) * 22);
  }

  // 6. Atualiza o HUD de Equipe e Notificação de troca
  renderPartyHUD();
  if (typeof renderHeroAvatars === 'function') renderHeroAvatars();
  if (typeof updateMapStatus === 'function') updateMapStatus();

  if (!silent) {
    const def = HERO_DEFINITIONS[novoHeroId];
    const nome = def ? def.name : novoHeroId;
    showToast(`⚡ ${nome} entrou em batalha!`);
  }

  // 7. Persiste a troca no save do navegador
  if (typeof savePlayerData === 'function') savePlayerData();
  return true;
}

function renderPartyHUD() {
  const container = document.getElementById('partyHud');
  if (!container) return;

  for (let idx = 0; idx < 2; idx++) {
    const slotEl = document.getElementById(`partySlot${idx}`);
    const imgEl = document.getElementById(`partyAvatar${idx}`);
    const hpFillEl = document.getElementById(`partyHpFill${idx}`);
    if (!slotEl) continue;

    const heroId = partyState.party[idx];
    const def = heroId ? HERO_DEFINITIONS[heroId] : null;
    const isCurrentActive = idx === partyState.activePartyIndex && selectedHeroId === heroId;

    slotEl.classList.toggle('active', isCurrentActive);
    slotEl.classList.toggle('empty', !heroId);

    if (imgEl) {
      if (def) {
        imgEl.src = def.face || def.avatar || 'assets/personagens/herois/achilles_face.png';
        imgEl.alt = def.name;
        slotEl.title = `${def.name} · Clave de ${def.clave || '—'} · ${def.papel || def.class}`;
      } else {
        // Vaga aberta: um rosto emprestado ali só confundia. O silhueta vazia é o
        // convite ao primeiro sorteio.
        imgEl.removeAttribute('src');
        imgEl.alt = 'Vaga aberta';
        slotEl.title = 'Vaga aberta — conquiste um companheiro no Sorteio';
      }
    }

    if (hpFillEl) {
      const hs = heroId ? partyState.heroStates[heroId] : null;
      const maxH = typeof playerMaxHp === 'function' ? playerMaxHp() : 100;
      const curH = hs ? (hs.hp !== undefined ? hs.hp : maxH) : maxH;
      const pct = Math.max(0, Math.min(100, (curH / maxH) * 100));
      hpFillEl.style.width = pct + '%';
    }
  }
}
const heroImages = {};
const processedHeroSprites = {};

function hero_isPNG(id) {
  const def = HERO_DEFINITIONS[id];
  return def && def.src && def.src.toLowerCase().endsWith('.png');
}

// Folhas extras por estado, guardadas por caminho. Ficam fora de processedHeroSprites
// porque aquele mapa é por personagem, e um personagem agora tem várias folhas.
const folhasDoHeroi = {};
// Medidas por folha, lidas de achilles_folhas.json: célula, corpo (altura pés→cabeça) e
// base (onde a linha dos pés cai dentro da célula). São elas que permitem misturar
// folhas de tamanhos diferentes sem o personagem pular de tamanho.
const medidasDasFolhas = {};

async function carregarMedidasDasFolhas() {
  for (const hero of Object.values(HERO_DEFINITIONS)) {
    if (!hero.medidas) continue;
    try {
      const r = await fetch(hero.medidas + '?t=' + Date.now());
      Object.assign(medidasDasFolhas, await r.json());
    } catch (e) { console.warn('[Acordelot] ficha de folhas não carregou:', e); }
  }
}

function loadHeroSprites() {
  for (const [id, hero] of Object.entries(HERO_DEFINITIONS)) {
    const img = new Image();
    img.onload = () => { processHeroSprite(id, img); renderHeroAvatars(); };
    img.src = hero.src;
    heroImages[id] = img;

    for (const estado of Object.values(hero.folhas || {})) {
      if (folhasDoHeroi[estado.src]) continue;
      const extra = new Image();
      extra.src = estado.src;
      folhasDoHeroi[estado.src] = extra;
    }
  }
  carregarMedidasDasFolhas();
}

// Qual folha desenhar agora, com as medidas dela junto. Devolve null enquanto a imagem
// ou a ficha não chegaram — melhor manter a folha anterior que piscar.
function folhaAtualDoHeroi(atacando) {
  const P = personagemAtivo();
  const f = P.folhas;
  if (!f) return null;

  const golpe = atacando && golpeEmCurso ? f[golpeEmCurso.folha] : null;
  // Parado tem duas caras: em guarda logo depois de um golpe, relaxado depois disso.
  const emGuarda = !player.isMoving && !atacando && performance.now() < guardaAte && f.guarda;
  const querParado = !player.isMoving && !atacando && !emGuarda && f.parado;
  const alvo = golpe || (emGuarda ? f.guarda : (querParado ? f.parado : (f.andar || null)));
  if (!alvo) return null;

  const img = folhasDoHeroi[alvo.src];
  if (!img || !img.complete || img.naturalWidth < 10) return null;
  const m = medidasDasFolhas[alvo.src.split('/').pop()];
  if (!m) return null;

  // `parado` liga o relógio da respiração; vale também para a guarda, que também é um
  // ciclo no tempo e não uma pose congelada.
  return { img, m, cols: m.cols, rows: m.rows,
           parado: alvo === f.parado || alvo === f.guarda, atacando: !!golpe };
}

function processHeroSprite(id, imgRaw) {
  try {
    if (!imgRaw || !imgRaw.complete || imgRaw.naturalWidth < 10) return;
    const off = document.createElement('canvas');
    off.width = imgRaw.naturalWidth;
    off.height = imgRaw.naturalHeight;
    const oc = off.getContext('2d');
    oc.drawImage(imgRaw, 0, 0);

    // PNG heroes (Lucian, Elena, Lyra) are native RGBA — no getImageData needed.
    // Only strip white for Arthur's JPG spritesheet (no alpha channel).
    if (!hero_isPNG(id)) {
      try {
        const idata = oc.getImageData(0, 0, off.width, off.height);
        const d = idata.data;
        for (let i = 0; i < d.length; i += 4) {
          if (d[i] > 215 && d[i+1] > 215 && d[i+2] > 215) d[i+3] = 0;
        }
        oc.putImageData(idata, 0, 0);
      } catch(e) { /* canvas security — keep as-is */ }
    }

    processedHeroSprites[id] = off;
    if (id === selectedHeroId) processedSprite = off;
  } catch(e) {}
}

function renderHeroAvatars() {
  for (const [id] of Object.entries(HERO_DEFINITIONS)) {
    // Priority: processed canvas → raw HTMLImageElement → processedSprite (Arthur fallback)
    const spr = processedHeroSprites[id];
    const img = heroImages[id];
    const src = (spr && spr.width > 10) ? spr
              : (img && img.complete && img.naturalWidth > 10) ? img
              : (id === 'arthur' && processedSprite && processedSprite.width > 10) ? processedSprite
              : null;
    if (!src) continue;

    const card = document.querySelector(`.hero-select-card[data-heroid="${id}"]`);
    if (!card) continue;
    const box = card.querySelector('.hero-avatar-box');
    if (!box) continue;

    const srcW = src instanceof HTMLImageElement ? src.naturalWidth  : src.width;
    const srcH = src instanceof HTMLImageElement ? src.naturalHeight : src.height;
    const frameW = Math.floor(srcW / 4);
    const frameH = Math.floor(srcH / 4);

    const av = document.createElement('canvas');
    av.width = 52; av.height = 52;
    const ac = av.getContext('2d');
    ac.imageSmoothingEnabled = false;
    ac.fillStyle = '#0f172a';
    ac.fillRect(0, 0, 52, 52);

    try {
      // Front-facing frame: row 0, col 0, top 70% of frame height (head + torso)
      ac.drawImage(src, 0, 0, frameW, Math.floor(frameH * 0.70), 2, 2, 48, 48);
      box.innerHTML = '';
      box.appendChild(av);
    } catch(e) {}
  }
  renderPartyHUD();
}

function initMainMenu() {
  const mainMenuOverlay = document.getElementById('mainMenuOverlay');
  const menuPlayerName = document.getElementById('menuPlayerName');
  const startAdventureBtn = document.getElementById('startAdventureBtn');
  const heroCards = document.querySelectorAll('.hero-select-card');

  renderHeroAvatars();

  // Keep retrying until all 4 hero avatars are rendered (images load async)
  (function pollAvatars() {
    const allDone = Object.keys(HERO_DEFINITIONS).every(id => {
      const spr = processedHeroSprites[id];
      return (spr && spr.width > 10) ||
             (heroImages[id] && heroImages[id].complete && heroImages[id].naturalWidth > 10);
    });
    renderHeroAvatars();
    if (!allDone) setTimeout(pollAvatars, 120);
  })();

  heroCards.forEach(card => {
    card.addEventListener('click', () => {
      heroCards.forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      selectedHeroId = card.dataset.heroid;
      const spr = processedHeroSprites[selectedHeroId];
      if (spr && spr.width > 10) processedSprite = spr;
    });
  });

  document.getElementById('continueBtn')?.addEventListener('click', () => {
    initAudio(); continuarJogo();
  });

  startAdventureBtn?.addEventListener('click', async () => {
   try {
    if (menuPlayerName && menuPlayerName.value.trim()) {
      playerName = menuPlayerName.value.trim();
    }
    mainMenuOverlay?.classList.add('hidden');

    try { localStorage.removeItem(CHAVE_DAS_CENAS); } catch (e) {}

    // Aventura nova começa sem ferramentas: o martelo precisa ser conquistado na forja,
    // senão a missão do Dorn nasce cumprida e o jogador já entra em cena armado.
    reiniciarProgressoDeJogo();

    // O ponto de partida vem do menu: uma cena específica, ou direto no mapa inicial.
    const escolha = document.getElementById('menuStartPoint')?.value || '';
    const cenaEscolhida = escolha.startsWith('cena:')
      ? CUT.roteiros.find(r => r.id === escolha.slice(5)) : null;

    const modoLivre = escolha === 'livre';
    const startMapKey = modoLivre ? ((startMap && cenarioExiste(startMap)) ? startMap : chavesDeCenario()[0])
      : (cenaEscolhida?.mapa
      || ((startMap && cenarioExiste(startMap)) ? startMap : 'custom_1785173102424_996'));
    if (cenarioExiste(startMapKey)) {
      currentKey = startMapKey;
      if (activeMapSelect) activeMapSelect.value = startMapKey;
      updateMapStatus();
    }

    // Marcar TODAS as outras cenas como vistas matava a continuação: as cenas seguintes
    // nasciam bloqueadas e o arco parava de andar. Só as anteriores à escolhida são
    // puladas — e o estado que elas dariam (missões concluídas) é aplicado junto, para
    // que quem começa no meio da história não fique com pré-requisito faltando.
    CUT.jaRodou = {};
    const ordem = CUT.roteiros.indexOf(cenaEscolhida);
    if (ordem > 0) {
      CUT.roteiros.slice(0, ordem).forEach(r => {
        marcarCenaRodada(r);
        (r.passos || []).forEach(p => {
          if (p.cmd === 'missao' && p.id && !completedQuests.includes(p.id)) completedQuests.push(p.id);
          // BANDEIRA e RECRUTAR faltavam. Comecar pela cena N deixava o jogador sem as
          // bandeiras das cenas 1..N-1, entao o estado do mundo nao correspondia ao ponto
          // da historia: heroi que ja devia estar no grupo nao estava, e cena que so
          // deveria abrir depois continuava trancada por uma bandeira que ninguem levantou.
          if (p.cmd === 'bandeira' && p.id) marcarBandeira(p.id);
          if (p.cmd === 'recrutar' && p.heroi) {
            // Mesmo efeito do `case 'recrutar'`: a bandeira e a fonte da verdade, e o
            // `aplicarHeroisRecrutados` no boot le ela para reconstruir o grupo.
            const h = HERO_DEFINITIONS[p.heroi];
            if (h && !h.desbloqueado) {
              h.desbloqueado = true;
              const vaga = partyState.party.findIndex(x => !x);
              if (vaga >= 0) partyState.party[vaga] = p.heroi;
            }
            marcarBandeira('heroi_' + p.heroi);
          }
          if (p.cmd === 'dar') {
            if (p.item === 'clave') claveCount += (p.quantidade || 1);
            else playerInventory[p.item] = (playerInventory[p.item] || 0) + (p.quantidade || 1);
          }
        });
      });
      updateInventorySlotsUI?.();
    }

    // Cada cena pode declarar o estado que ela pressupõe (`estadoInicial` no JSON).
    // Começar pela Cena 10 sem Ressonador deixava o jogador preso: o diálogo dizia
    // que ele já tinha um. Agora entrar no meio da história entrega o que a história
    // já teria entregado.
    // Modo livre: nada de cena, tudo liberado. É a porta de entrada para editar o mundo
    // andando por ele, como se a história inteira já tivesse acontecido.
    if (modoLivre) {
      CUT.roteiros.forEach(r => marcarCenaRodada(r));
      questsData.forEach(q => { if (!completedQuests.includes(q.id)) completedQuests.push(q.id); });
      activeQuests = [];
      aplicarEstadoInicial({ estadoInicial: {
        nivel: 8, claves: 40, moedas: 900,
        forjar: ['hammer_ferro', 'reson_cobre', 'axe_bronze', 'pick_bronze'],
        qualidade: 'ressonante',
        itens: { fragmento: 60, fragmento_puro: 10, tom: 10, semitom: 6, wood: 30, stone: 30, potions: 5 },
        notas: CROMATICA.map(n => n.id),
      }});
      showToast('🔓 Modo livre — todas as cenas já vistas, tudo desbloqueado.');
    }

    window.__mapaDefinidoPelaCena = modoLivre || !!(cenaEscolhida?.mapa || cenaEscolhida?.estadoInicial?.mapa);
    if (!modoLivre) aplicarEstadoInicial(cenaEscolhida);

    jogoIniciado = false; ultimaPosicaoDeJogo = null;   // partida nova, do começo
    if (!isPlayMode) togglePlay();
    window.__mapaDefinidoPelaCena = false;

    if (wantsMobilePlay() || document.body.classList.contains('mobile-play')) {
      document.getElementById('touchControls')?.classList.remove('hidden');
    }

    // A primeira cena ja nasce armada: pedir aceite antes de o jogo comecar seria pedir
    // que o jogador aceitasse algo que ele ainda nao sabe o que e. Da segunda em diante,
    // quem decide e ele, pelo pergaminho.
    const primeira = cenaEscolhida || cenasOferecidas()[0];
    if (primeira) cenaAceita = primeira.id;
    if (cenaEscolhida) iniciarCena(cenaEscolhida);
    else showToast(`⚔️ Bem-vindo a Acordelot, ${playerName}!`);
   } catch (err) {
    // Sair do menu sem entrar no jogo é o pior desfecho possível: garante o play mode.
    console.error('Falha ao iniciar a aventura:', err);
    if (!isPlayMode) togglePlay();
    showToast('⚠️ A aventura começou, mas a abertura falhou — veja o console.');
   }
  });
}

function initQuestBuilder() {
  const createQuestBtn = document.getElementById('createQuestBtn');
  const questTitleInput = document.getElementById('questTitleInput');
  const questDescInput = document.getElementById('questDescInput');
  const questTypeSelect = document.getElementById('questTypeSelect');
  const questAmountInput = document.getElementById('questAmountInput');
  const questRewardSelect = document.getElementById('questRewardSelect');

  createQuestBtn?.addEventListener('click', () => {
    const title = questTitleInput?.value.trim() || 'Nova Missão';
    const desc = questDescInput?.value.trim() || 'Complete o objetivo para ganhar a recompensa.';
    const type = questTypeSelect?.value || 'collect';
    const amount = parseInt(questAmountInput?.value || '3', 10);
    const reward = questRewardSelect?.value || '100 XP + Poção de Vida';

    const newQuest = {
      id: `quest_${Date.now()}`,
      title: title,
      description: desc,
      type: type,
      targetAmount: amount,
      currentAmount: 0,
      reward: reward,
      completed: false,
      active: true
    };

    questsData.push(newQuest);
    renderQuestBuilderList();
    activateQuestInGame(newQuest);
    showToast(`✨ Missão "${title}" Criada e Ativada!`);

    if (questTitleInput) questTitleInput.value = '';
    if (questDescInput) questDescInput.value = '';
  });

  renderQuestBuilderList();
}

function renderQuestBuilderList() {
  const questListBuilder = document.getElementById('questListBuilder');
  if (!questListBuilder) return;
  if (!questsData.length) {
    questListBuilder.innerHTML = `<div class="empty-msg">Nenhuma missão criada ainda</div>`;
    return;
  }

  questListBuilder.innerHTML = questsData.map((q, idx) => `
    <div class="quest-card-item">
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <span class="quest-card-title">📜 ${q.title || 'Missão'}</span>
        <span class="quest-type-tag quest-type-${q.type || 'collect'}">${q.type || 'coleta'}</span>
      </div>
      <div style="font-size:10px; color:#cbd5e1;">${q.description || ''}</div>
      <div style="font-size:9px; color:#f59e0b; font-weight:bold;">Progresso: ${q.currentAmount || 0}/${q.targetAmount || 3} · Recompensa: ${q.reward || '100 XP'}</div>
      <button class="btn-card-add" onclick="testQuest(${idx})" style="background:#d97706; margin-top:4px;">▶ Testar Missão em Tempo Real</button>
    </div>
  `).join('');
}

function activateQuestInGame(q) {
  const notif = document.getElementById('questNotification');
  const titleEl = document.getElementById('questNotifTitle');
  const objEl = document.getElementById('questNotifObj');
  if (titleEl) titleEl.textContent = `📜 ${q.title}`;
  if (objEl) objEl.textContent = `${q.description} (${q.currentAmount || 0}/${q.targetAmount || 3})`;
  notif?.classList.remove('hidden');
}

window.testQuest = function(idx) {
  const q = questsData[idx];
  if (!q) return;
  q.completed = false;
  q.currentAmount = 0;
  q.active = true;
  activateQuestInGame(q);
  showToast(`▶ Testando Missão: "${q.title}"`);
};

async function finishInit(){
  // Nove `await` em fila esperavam um ao outro sem nenhum precisar do anterior: cada
  // ida ao servidor só começava quando a de cima terminava, e o menu só aparecia no
  // fim de todas. O config vem primeiro porque as camadas dependem da lista de
  // cenários; o resto vai junto, em paralelo.
  await loadWorldConfig();
  await Promise.all([
    loadLayers(), loadNPCs(), loadQuests(), loadShopCatalog(),
    loadMonsters(), loadObjetos(), loadMundo(), loadSkillTree(),
  ]);
  refreshMapSelect();
  renderQuestBuilderList();
  // Aqui havia três tentativas, em 200/700/1500 ms, de clicar na aba do Criador de
  // Mundo ao abrir /edit. Com o modo arquivado elas ficaram sem alvo — e eram elas que
  // sequestravam a abertura para uma tela que não se usa mais.
  // A paleta de props precisa de duas passadas: uma agora, com o catálogo já lido, e
  // outra quando os PNGs terminarem de decodificar — só então há miniatura para mostrar.
  renderPaletaDeProps();
  setTimeout(renderPaletaDeProps, 700);
  loadingOverlay?.classList.add('hidden');updateMapStatus();
  showToast('🎵 Acordelot Engine carregado!');

  // Cena de abertura: roda uma vez por jogador, e nunca dentro do editor.
  try { CUT.jaRodou = JSON.parse(localStorage.getItem(CHAVE_DAS_CENAS) || '{}'); } catch (e) {}
  await carregarCatalogoDeCenas();
  preencherMenuDeCenas();
  abrirMenuInicialSePreciso();   // de novo: agora o catálogo existe e o menu fica coerente
  if (wantsMobilePlay()) talvezIniciarCenaDoMapa(currentKey);
}
setTimeout(()=>{
  loadingOverlay?.classList.add('hidden');
  // Pré-tela: só depois que tudo carregou, e só quando se vai de fato JOGAR. No editor
  // ela atrapalharia quem está montando cenário.
  //
  // A PORTARIA vem antes dela: primeiro se decide de quem é a partida, só então a
  // pré-tela mostra em quem você está e onde parou. Na ordem inversa o jogador escolhe o
  // herói e o nível de uma partida que a conta pode substituir logo em seguida.
  if (IS_PLAY_BUILD || wantsMobilePlay()) {
    portariaDaConta().catch(() => {}).then(abrirPreTela);
  }
},1500);

// ============================================================
// VISUAL DIALOGUE EDITOR LOGIC
// ============================================================
let dialogueEditorOverlay, dlgEditorNpcName, dlgEditorId, dlgEditorLines, dlgEditorQuest;
let openDlgEditorBtn, closeDlgEditorBtn, saveDlgBtn, testDlgBtn;

function initDialogueEditor() {
  dialogueEditorOverlay = document.getElementById('dialogueEditorOverlay');
  dlgEditorNpcName = document.getElementById('dlgEditorNpcName');
  dlgEditorId = document.getElementById('dlgEditorId');
  dlgEditorLines = document.getElementById('dlgEditorLines');
  dlgEditorQuest = document.getElementById('dlgEditorQuest');
  openDlgEditorBtn = document.getElementById('openDlgEditorBtn');
  closeDlgEditorBtn = document.getElementById('closeDlgEditorBtn');
  saveDlgBtn = document.getElementById('saveDlgBtn');
  testDlgBtn = document.getElementById('testDlgBtn');

  openDlgEditorBtn?.addEventListener('click', () => {
    if (!selectedNPC) { showToast('⚠️ Selecione um NPC na cena primeiro!'); return; }
    openDialogueEditor(selectedNPC);
  });

  closeDlgEditorBtn?.addEventListener('click', () => {
    dialogueEditorOverlay?.classList.add('hidden');
  });

  saveDlgBtn?.addEventListener('click', async () => {
    await saveDialogueFromEditor();
  });

  testDlgBtn?.addEventListener('click', async () => {
    await testDialogueFromEditor();
  });
}

async function openDialogueEditor(npc) {
  if (!npc) return;
  dlgEditorNpcName.value = npc.name || '';
  const dlgId = (npc.dialogue && npc.dialogue !== 'none') ? npc.dialogue : `${npc.id}_dlg`;
  dlgEditorId.value = dlgId;

  // Try loading existing dialogue
  const existing = await loadDialogue(dlgId);
  if (existing && existing.steps && existing.steps.length > 0) {
    const linesStep = existing.steps.find(s => s.type === 'lines' && s.lines);
    if (linesStep && linesStep.lines) {
      dlgEditorLines.value = linesStep.lines.join('\n');
    } else {
      dlgEditorLines.value = '';
    }
    const endStep = existing.steps.find(s => s.quest_unlock);
    if (endStep && dlgEditorQuest) dlgEditorQuest.value = endStep.quest_unlock;
    else if (dlgEditorQuest) dlgEditorQuest.value = '';
  } else {
    dlgEditorLines.value = `Olá viajante!\nSeja bem-vindo a Acordelot.`;
    if (dlgEditorQuest) dlgEditorQuest.value = '';
  }

  dialogueEditorOverlay?.classList.remove('hidden');
}

async function saveDialogueFromEditor() {
  if (IS_PLAY_BUILD) return;
  if (!selectedNPC) { showToast('⚠️ Nenhum NPC selecionado!'); return; }

  const dlgId = dlgEditorId.value.trim().replace(/[^a-zA-Z0-9_]/g, '_') || `${selectedNPC.id}_dlg`;
  const npcName = dlgEditorNpcName.value.trim() || selectedNPC.name;
  const rawLines = dlgEditorLines.value.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  const lines = rawLines.length > 0 ? rawLines : ['...'];
  const questUnlock = dlgEditorQuest ? dlgEditorQuest.value : '';

  const dialogueJson = {
    npc_id: selectedNPC.id,
    npc_name: npcName,
    steps: [
      {
        id: "start",
        type: "lines",
        lines: lines,
        next: questUnlock ? "quest_step" : "end"
      },
      ...(questUnlock ? [
        { id: "quest_step", type: "end", quest_unlock: questUnlock }
      ] : [
        { id: "end", type: "end" }
      ])
    ]
  };

  // Cache in memory
  dialogueCache[dlgId] = dialogueJson;

  // Save to disk via server API (somente no ambiente local Python)
  if (podeSalvarLocalPython()) try {
    await fetch('/save_dialogue', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: dlgId, dialogue: dialogueJson })
    });
  } catch(e) {}

  // Assign to NPC
  selectedNPC.dialogue = dlgId;
  selectedNPC.name = npcName;

  // Add to select dropdown
  if (inspDialogue) {
    let exists = false;
    for (let opt of inspDialogue.options) {
      if (opt.value === dlgId) { exists = true; break; }
    }
    if (!exists) {
      const opt = document.createElement('option');
      opt.value = dlgId;
      opt.textContent = dlgId;
      inspDialogue.appendChild(opt);
    }
    inspDialogue.value = dlgId;
  }

  syncInspector(selectedNPC);
  refreshNPCHierarchy();
  saveNPCs();

  dialogueEditorOverlay?.classList.add('hidden');
  showToast(`💬 Diálogo "${dlgId}" salvo e vinculado a ${npcName}!`);
}

async function testDialogueFromEditor() {
  await saveDialogueFromEditor();
  dialogueEditorOverlay?.classList.add('hidden');
  if (!isPlayMode) togglePlay();
  if (selectedNPC) {
    setTimeout(() => startDialogue(selectedNPC), 150);
  }
}

// ============================================================
// PALETA DE MONSTROS
// ============================================================
// Até aqui só dava para DUPLICAR um monstro que já estivesse no mapa: um tipo novo em
// monsters.json não tinha porta de entrada nenhuma. Esta paleta se monta a partir dos
// próprios tipos, então bicho novo no arquivo aparece aqui sozinho — ninguém precisa
// lembrar de acrescentar um cartão à mão.

let monstroParaColocar = null;   // tipo armado, esperando o clique no mapa

function renderPaletaDeMonstros() {
  const grade = document.getElementById('mobGalleryGrid');
  if (!grade || !monsterDefs) return;
  grade.innerHTML = '';

  for (const [tipo, def] of Object.entries(monsterDefs)) {
    const card = document.createElement('div');
    card.className = 'npc-gallery-card' + (monstroParaColocar === tipo ? ' armado' : '');
    card.title = `${def.name} — ${def.hp} de vida, ${def.damage} de dano`;

    // A miniatura sai do MESMO recorte que o jogo usa, e não da folha inteira: assim o
    // que se vê na paleta é exatamente o que vai para o mapa.
    const spr = monsterSprites[tipo];
    if (spr) {
      const cv = document.createElement('canvas');
      cv.width = 64; cv.height = 64;
      const cx = cv.getContext('2d');
      cx.imageSmoothingEnabled = false;
      const esc = Math.min(64 / spr.sw, 64 / spr.sh);
      const w = spr.sw * esc, h = spr.sh * esc;
      cx.drawImage(spr.canvas, spr.sx, spr.sy, spr.sw, spr.sh, (64 - w) / 2, 64 - h, w, h);
      cv.className = 'gallery-thumb';
      card.appendChild(cv);
    } else {
      const d = document.createElement('div');
      d.className = 'thumb-empty'; d.textContent = '👾';
      card.appendChild(d);
    }

    const info = document.createElement('div');
    info.className = 'npc-card-info';
    info.innerHTML = `<span class="npc-card-name">${def.name || tipo}</span>` +
                     `<span class="npc-card-type">${def.hp} vida · ${def.damage} dano</span>`;
    card.appendChild(info);

    const b = document.createElement('button');
    b.className = 'btn-card-add';
    b.textContent = monstroParaColocar === tipo ? '✓ clique no mapa' : '＋ Colocar';
    card.appendChild(b);

    // Armar e clicar no mapa, como os props. Largar tudo no centro da tela obrigaria a
    // caçar o bicho e arrastar, e ele cairia em cima do que já estivesse ali.
    card.addEventListener('click', () => {
      if (engineMode !== 'scene') setMode('scene');
      monstroParaColocar = (monstroParaColocar === tipo) ? null : tipo;
      npcPlacingMode = false;
      propParaColocar = null;
      canvas?.classList.toggle('cursor-crosshair', !!monstroParaColocar);
      renderPaletaDeMonstros();
      if (monstroParaColocar) showToast(`👾 ${def.name}: clique no mapa para posicionar`);
    });

    grade.appendChild(card);
  }
}

function colocarMonstro(x, y) {
  const tipo = monstroParaColocar;
  const def = monsterDefs[tipo];
  if (!def) return false;
  const mapa = activeMapSelect?.value || currentKey;
  const novo = {
    id: `${tipo}_${Date.now()}`,
    type: tipo, mapKey: mapa,
    x: Math.round(x), y: Math.round(y),
    homeX: Math.round(x), homeY: Math.round(y),
    hp: def.hp, maxHp: def.hp,
    escala: 1, flipX: false, dead: false,
  };
  monsters.push(novo);
  selectedMonster = novo;
  mostrarInspetorDeMonstro?.(novo);
  refreshNPCHierarchy?.();
  saveMonsters();
  showToast(`👾 ${def.name} posicionado`);
  return true;
}

